    method: "POST",
    headers: { "Content-Type": "application/json", apikey: SUPABASE_ANON_KEY, Authorization: authHeader },
    body: JSON.stringify({ p_amount: amount, p_ref: ref, p_reason: reason, p_partial: !!partial }),
    signal: AbortSignal.timeout(10000),
