/** One message to the queue that writes progress; false when there is no queue or it would not take it. */
async function sendProgressTask(env, task, delayS = 0) {
  // AWAITED (2026-10-19, deploy 2224's diagnostic): asked from the container's
  // gateway, an unawaited call to the room died with the request, and the
  // queue's message took 3½ minutes to come — the first line waited 211 s.
  await roomWriter(env, task, delayS);
  if (!env || !env.BUILD_QUEUE || typeof env.BUILD_QUEUE.send !== "function") return false;
  try {
    await env.BUILD_QUEUE.send({ kind: PROGRESS_KIND, id: task.id, uid: task.uid }, delayS > 0 ? { delaySeconds: queueDelay(delayS) } : undefined);
    return true;
  } catch (e) {
    console.error("progress: could not queue", task.id, errorClassForLog(e));
    return false;
  }
}

/**
 * ASK FOR A WRITER WHERE THE RECORD NEEDS ONE (`writerNeeded`): the ask is
 * written on the record first, so of two that ask at once one message is
 * sent. What it was: "asked", or the rule's own answer.
 */
async function askProgress(env, job, uid, now = Date.now()) {
  let need = "none";
  const r = await progressUpdate(env, job, (rec) => {
    need = writerNeeded(rec, now);
    if (need !== "ask" || rec.uid !== uid) return null;
    return { rec: markAsked(rec, now) };
  });
  if (!r) return need === "ask" ? "unasked" : need;
  await sendProgressTask(env, { id: job, uid });
  return "asked";
}

/**
 * WHAT THE JOB TELLS ITS RECORD — the one door for the recorder in the Worker
 * and for the gateway's `/progress` from the container; `ids` are the job's
 * own (the gateway reads them off its token, never off the body). `body.op`:
 *   begin   the record opened by this run, with the customer's words, the
 *           picked model and the site's pages; a record another run opened is
 *           not this run's — refused;
 *   mark    one milestone, numbered by the recorder (`seq`), so one whose
 *           write is made twice is added once; a writer asked for when none
 *           is on it;
 *   close   the record closed at the job's end: nothing added or said after.
 */
async function progressFromJob(env, ids, body) {
  const { id, uid, slug } = ids || {};
  // A PRE-SCOPED BUILD (2026-10-19) writes its own build record and nothing else.
  const pre = !!(ids && ids.pre === true);
  if (!progressOn(env) || !env || !env.SITES_BUCKET || !isJobId(id) || typeof uid !== "string" || !uid) return { ok: false };
  const b = body && typeof body === "object" && !Array.isArray(body) ? body : {};
  const run = typeof b.run === "string" ? b.run : "";
  const now = Date.now();
  // THE STORE'S FAILURE IS NOT A REFUSAL (2026-10-06): the answer says so
  // (`retry`), and the recorder sends the same body again; a refusal — a
  // closed record, another run's, a fact that does not read — it never does.
  const seen = {};
  const answer = (r) => (r ? { ok: true } : seen.store ? { ok: false, retry: true } : { ok: false });
  if (b.op === "begin") {
    // A PAGE-FILED JOB'S ONE TASK (`task`), in the customer's words, for its
    // card on another device to be named by the model's own line for it; a
    // request's part is named on the request's record (`syncRequestTasks`).
    const words = typeof b.words === "string" ? b.words.trim() : "";
    const r = await progressUpdate(env, id, (rec) => {
      // A BUILD CARRIED ON BY ITS NEXT RUN (round 5) takes its record over.
      if (rec && b.kind === "build" && b.take === true && rec.run !== run) { const t = takeOverRecord(rec, { run, uid }); return t ? { rec: t } : null; }
      if (pre && (b.kind !== "build" || (rec && rec.op !== "build"))) return null;
      if (rec) return rec.run === run && rec.uid === uid ? { done: true } : null;
      // CONVERSATIONAL ONLY WHEN THE JOB ASKED FOR IT AND THE SWITCH IS ON HERE
      // (talk, 2026-10-13): the record keeps the flag for its whole life.
      const opened = openRecord({ job: id, uid, slug, op: b.kind, run, words: b.words, picker: b.picker, pages: b.pages, tasks: b.task === true && words ? [{ n: 0, words }] : [], at: now, request: b.request, talk: b.talk === true && talkOn(env) });
      return opened ? { rec: opened } : null;
    }, seen);
    if (r && XAI_EFFORTS.includes(b.effort)) { try { await env.SITES_BUCKET.put(progressEffortKey(id), b.effort); } catch { /* the talk falls back to low */ } }
    await diag(env, id, r ? "begun" : "begin-refused", { kind: String(b.kind || ""), take: b.take === true, pre, store: !!seen.store });
    if (r) await askProgress(env, id, uid, now);
    return answer(r);
  }
  if (b.op === "mark") {
    let ask = false;
    let settle = 0;
    const r = await progressUpdate(env, id, (rec) => {
      if (!rec || rec.run !== run || rec.uid !== uid || (pre && rec.op !== "build")) return null;
      const added = appendMark(rec, { stage: b.stage, facts: b.facts, at: now, key: b.seq });
      // A WRITE MADE AGAIN BECAUSE ITS FIRST ANSWER WAS LOST: whether that one
      // asked for a writer cannot be told, so one is asked again — a second
      // writer finds the first one's lease, or nothing waiting, and leaves.
      if (added.already) { ask = !writerLive(rec, now) && pendingMarks(rec).length > 0; return { done: true }; }
      if (!added.rec) {
        if (added.refused !== "closed") console.log("progress:", id, "milestone refused —", added.refused);
        diag(env, id, "mark-refused", { stage: String(b.stage || "").slice(0, 40), why: String(added.refused || "") });
        return null;
      }
      ask = writerNeeded(added.rec, now) === "ask";
      // A CONVERSATIONAL RECORD'S WRITER IS ASKED A FEW SECONDS LATER (talk,
      // `PROGRESS_SETTLE_S`), so milestones landing close together are said in
      // one update; the ask is recorded now, so nobody else asks meanwhile.
      settle = added.rec.talk === true ? PROGRESS_SETTLE_S : 0;
      return { rec: ask ? markAsked(added.rec, now) : added.rec };
    }, seen);
    await diag(env, id, r ? "marked" : "mark-not-written", { stage: String(b.stage || "").slice(0, 40), ask, store: !!seen.store });
    if (r && ask) await sendProgressTask(env, { id, uid }, settle);
    return answer(r);
  }
  if (b.op === "close") {
    await diag(env, id, "close", { why: String(b.why || "").slice(0, 40) });
    const r = await progressUpdate(env, id, (rec) => {
      if (!rec || rec.run !== run || rec.closed || (pre && rec.op !== "build")) return { done: true };
      const closed = closeRecord(rec, typeof b.why === "string" ? b.why : "ended", now);
      // …OWING ITS LATE LINE (`lateBatch`): a writer is asked now.
      return lateNeeded(closed) && writerNeeded(closed, now) === "ask" ? { rec: markAsked(closed, now), ask: true } : { rec: closed };
    }, seen);
    if (r && r.ask) await sendProgressTask(env, { id, uid }, PROGRESS_SETTLE_S);
    return answer(r);
  }
  return { ok: false };
}

/**
 * THE JOB'S RECORDER, made where the job is claimed and carried on its
 * context (`makeJobCtx`): null with progress off. Every write waits its turn
 * on one chain and is held by the invocation's own life (`ctx.waitUntil`);
 * none can throw into the job, and none is awaited by its work. `close` lets
 * the milestones already on their way land first, then closes — bounded, so
 * a store that hangs costs the job's end at most `PROGRESS_CLOSE_MS`.
 *
 * A DELIVERY THAT FAILS IS KEPT AND SENT AGAIN (2026-10-06, the owner: *"Fix
 * makeProgress dropping a milestone when JOB_PROGRESS fails: retain its
 * identity and retry automatically while appropriate, without needing another
 * milestone or an open browser, and prevent duplicates when the first
 * delivery landed but its response was lost."*). The opening and each
 * milestone are sent as one body — the milestone under its own number — and a
 * try that did not reach the record (the network, a timeout, the gateway's or
 * the store's failure: `retry`) is made again after each of
 * `PROGRESS_SEND_WAITS_MS`, on the chain's own timer, so nothing else need
 * happen for it to land. A refusal (a closed record, another run's) is final.
 * A try that landed and whose answer was lost is recorded once: the record
 * knows the number (`appendMark`'s `already`). ORDER IS KEPT: the chain waits
 * for a milestone before the next, so the record's last milestone is always
 * the newest. The job's end cuts a wait short for one last try, and is never
 * held past `PROGRESS_CLOSE_MS`; the close itself is tried once — its landing
 * is no longer what keeps a late line from being shown (`confirmLines`).
 */
function makeProgress(env, ctx, { id, run, uid, slug, standalone = false }) {
  if (!progressOn(env) || !isJobId(id) || typeof run !== "string" || !run) return null;
  // CONVERSATIONAL (talk, 2026-10-13): read once, here, so every milestone of
  // the job is recorded the same way whatever the switch does meanwhile.
  const talk = talkOn(env);
  // THE WAY IN IS FIXED AT THE START: the container's gateway, held as it
  // was handed in, or the Worker's own door.
  const viaGateway = typeof env.JOB_PROGRESS === "function" ? env.JOB_PROGRESS : null;
  const send = viaGateway ? (b) => viaGateway(b) : (b) => progressFromJob(env, { id, uid, slug }, b);
  let chain = Promise.resolve();
  let seq = 0;
  let opened = false;
  let opening = null;
  // THE JOB'S END, ONCE ASKED FOR: no wait after it, and a wait already
  // running is cut short (`wake`) for the last try.
  let ending = false;
  let wake = null;
  const step = (fn) => {
    const p = chain.then(fn).catch((e) => { console.error("progress: could not record for", id, errorClassForLog(e)); return false; });
    chain = p.then(() => {}, () => {});
    if (ctx && typeof ctx.waitUntil === "function") { try { ctx.waitUntil(p); } catch { /* the record never costs the job */ } }
    return p;
  };
  /** One try: "ok", "refused" (never sent again), or "again" — it never reached the record. */
  const tryOnce = async (b) => {
    try {
      const r = await send(b);
      if (r && r.ok === true) return "ok";
      return r && r.retry === true ? "again" : "refused";
    } catch { return "again"; }
  };
  const pause = (ms) => new Promise((ok) => {
    const t = setTimeout(() => { wake = null; ok(); }, ms);
    wake = () => { clearTimeout(t); wake = null; ok(); };
  });
  /**
   * ONE DELIVERY, KEPT UNTIL IT IS ANSWERED: the same body each try, while the
   * job runs. ONCE ITS END IS ASKED FOR — before a try failed or during the
   * wait after one — one more try is made at once, and no more.
   */
  const deliver = async (b, what) => {
    for (let i = 0, last = false; ; i++) {
      const got = await tryOnce(b);
      if (got === "ok") return true;
      if (got === "refused") return false;
      if (last || i >= PROGRESS_SEND_WAITS_MS.length) {
        console.log("progress:", id, what, "not delivered after", i + 1, "tries");
        return false;
      }
      if (!ending) await pause(PROGRESS_SEND_WAITS_MS[i]);
      last = ending;
    }
  };
  // A RECORD THAT DID NOT OPEN IS OPENED AGAIN before the next milestone, so
  // one failed opening does not lose the job's every line.
  const open = async () => {
    if (opened || !opening) return opened;
    opened = await deliver({ op: "begin", run, ...opening }, "opening");
    return opened;
  };
  return {
    /** Whether this job's record is conversational: the wiring records its plan, checks and publish only then. */
    talk,
    begin({ op, words = "", picker = "", pages = [], request = null, take = false } = {}) {
      opening = {
        kind: op, words: typeof words === "string" ? words : "", picker: typeof picker === "string" ? picker : "", pages: Array.isArray(pages) ? pages : [],
        ...(take === true ? { take: true } : {}),
        ...(standalone ? { task: true } : {}),
        ...(talk ? { talk: true } : {}),
        // THE CUSTOMER'S EFFORT (2026-10-20, owner: "if they have low everything
        // is on low, if they have high everything is on high"): kept beside the
        // record, so its writer — which runs with no request of its own — uses it.
        ...(env && XAI_EFFORTS.includes(env.BUILD_EFFORT) ? { effort: env.BUILD_EFFORT } : {}),
        // THE JOB'S PLACE IN ITS REQUEST (2026-10-07): its writer reads the
        // request's other parts by it, as they stand when each line is written.
        ...(request && typeof request === "object" ? { request: { key: request.key, part: request.part } } : {}),
      };
      step(open);
    },
    mark(stage, facts) {
      if (!Array.isArray(facts) || !facts.length) return;
      const n = seq++;
      step(async () => ((await open()) ? deliver({ op: "mark", run, stage, facts, seq: n }, "milestone " + n) : false));
    },
    async close(why = "ended") {
      ending = true;
      if (wake) wake();
      const p = step(async () => (opened ? (await tryOnce({ op: "close", run, why })) === "ok" : true));
      let timer;
      try {
        await Promise.race([p, new Promise((ok) => { timer = setTimeout(() => ok(false), PROGRESS_CLOSE_MS); })]);
      } finally { if (timer) clearTimeout(timer); }
    },
  };
}

/**
 * A FIRST BUILD'S LIVE LINES (2026-10-09, parallel round 5), from its own
 * trace: every step the build really reaches is handed here (\`step\`) and
 * becomes milestone facts (\`buildStepFacts\`) the progress writer turns into
 * the model's own lines, exactly as an edit's are. The record opens once the
 * build knows its site's address (\`identify\`); steps before that are kept
 * and sent then. A later run of the same build (the resume) takes the record
 * over (\`take\`), so the lines carry on across the hand-over. Inert with
 * progress off, without a lease, or without a job.
 */
function buildProgressFor(env, ctx, { id, run, uid, take = false, words = "" }) {
  let p = null;
  const early = [];
  // THE QUIET STRETCHES (2026-10-19): when the build has said nothing new for
  // `STILL_AFTER_MS`, its last "doing" step is said again as still going
  // (`stillFacts`), at most once per stretch of that length. Stopped at close.
  let lastAt = Date.now(), lastDoing = "", stepAt = Date.now(), stillTimer = null;
  const mark = (stage, facts) => {
    const doing = facts.filter((f) => f && f.state === "doing").pop();
    if (stage !== "still") { if (doing && doing.text !== lastDoing) { lastDoing = doing.text; stepAt = Date.now(); } }
    lastAt = Date.now();
    p.mark(stage, facts);
  };
  const watchStill = () => {
    if (stillTimer || !p || !p.talk) return;
    stillTimer = setInterval(() => {
      try {
        if (!p || Date.now() - lastAt < STILL_AFTER_MS) return;
        const said = stillFacts(lastDoing, Date.now() - stepAt);
        if (said.length) mark("still", said);
      } catch { /* lines never cost the build */ }
    }, STILL_TICK_MS);
    try { if (stillTimer && typeof stillTimer.unref === "function") stillTimer.unref(); } catch { /* not every runtime has it */ }
  };
  const send = (step) => {
    // A CONVERSATIONAL RECORD (talk, 2026-10-13) hears the container's turn
    // as its result — the site built — beside every other step's own facts.
    const facts = (p && p.talk) || (!p && talkOn(env)) ? talkBuildStepFacts(step) : buildStepFacts(step);
    if (!facts.length) return;
    const stage = "build-" + String(step.s || "");
    if (p) mark(stage, facts); else if (early.length < 20) early.push([stage, facts]);
  };
  return {
    /**
     * OPEN AT THE START (2026-10-19, owner: "it needs to talk more"): a first
     * build's record opens before the design names the site, so its opening
     * plan is said in the first seconds instead of after the design. Never on a
     * run that carries a build on (`take`): that one opens at `identify`.
     */
    open() {
      // ONLY WHERE THE BUILD WILL RUN TO ITS END (2026-10-19, after deploy
      // 2219's build said one line and nothing more): the Worker's own run hands
      // a build to its container, and a record it opened belonged to the wrong
      // run — every later milestone was refused. Inside the container (its
      // gateway is the way in) the record opens at the start; elsewhere at
      // `identify`, as it always did.
      if (p || take || typeof env.JOB_PROGRESS !== "function") return;
      p = makeProgress(env, ctx, { id, run, uid, slug: "", standalone: false });
      if (!p) return;
      p.begin({ op: "build", words, take: false });
      if (p.talk) mark("start", startFacts({ op: "build", slug: "", draft: draftFirst(env) }));
      for (const [stage, facts] of early.splice(0)) mark(stage, facts);
      watchStill();
    },
    identify(slug) {
      if (typeof slug !== "string" || !slug) return;
      // ALREADY OPEN: the address the design chose is one more thing to say.
      if (p) { const said = p.talk && !take ? addressFacts(slug) : []; if (said.length) mark("address", said); return; }
      p = makeProgress(env, ctx, { id, run, uid, slug, standalone: false });
      if (!p) return;
      p.begin({ op: "build", words, take });
      // THE OPENING PLAN (talk, 2026-10-13), once — never again on the run that
      // carries a build on (`take`), whose record already said it.
      if (p.talk && !take) mark("start", startFacts({ op: "build", slug, draft: draftFirst(env) }));
      for (const [stage, facts] of early.splice(0)) mark(stage, facts);
      watchStill();
    },
    step(step) { try { if (step && typeof step === "object") send(step); } catch { /* lines never cost the build */ } },
    /** Facts a step has in words (a design part's decisions), marked as they are. */
    say(stage, facts) {
      try {
        if (typeof stage !== "string" || !Array.isArray(facts) || !facts.length) return;
        if (p) mark(stage, facts); else if (early.length < 20) early.push([stage, facts]);
      } catch { /* lines never cost the build */ }
    },
    close(why) { if (stillTimer) { clearInterval(stillTimer); stillTimer = null; } return p ? p.close(why) : Promise.resolve(); },
  };
}

/**
 * THE JOB'S ROW AS THE WRITER CHECKS IT — read fresh with the service key,
 * every time: the row, null when there is none, `undefined` when it could not
 * be read (`jobVerdict` refuses to write on either).
 */
async function jobRowForProgress(env, job) {
  if (!env || !env.SUPABASE_SERVICE_KEY || !isJobId(job)) return undefined;
  try {
    const r = await fetch(`${SUPABASE_URL}/rest/v1/edit_jobs?select=id,uid,state,lease_owner,lease_expires_at,cancel_requested_at,needs_review,op&id=eq.${encodeURIComponent(job)}`, { headers: svcHeaders(env) });
    if (!r.ok) return undefined;
    const rows = await r.json();
    if (!Array.isArray(rows)) return undefined;
    const row = rows.find((x) => x && x.id === job);
    return row || null;
  } catch (e) {
    console.error("progress: could not read the job", job, errorClassForLog(e));
    return undefined;
  }
}

/** A job the row says no line may be written for: its record closed with why; a row that could not be read is a try that failed. */
async function progressStops(env, job, owner, batch, why) {
  if (why === "unread") {
    const f = await progressUpdate(env, job, (rec) => {
      const out = failBatch(rec, { owner, marks: batch.marks, why: "row", now: Date.now() });
      return out ? { rec: out.rec, retry: out.retry } : null;
    });
    if (f && f.retry) await sendProgressTask(env, { id: job, uid: f.rec.uid }, Math.ceil(PROGRESS_RETRY_MS / 1000));
    return;
  }
  const c = await progressUpdate(env, job, (rec) => {
    const closed = closeRecord(rec, why, Date.now());
    if (!closed) return { done: true };
    // A WRITER THAT FOUND THE JOB ENDED leaves its late line asked for.
    return lateNeeded(closed) ? { rec: markAsked(closed, Date.now()), ask: true } : { rec: closed };
  });
  if (c && c.ask && c.rec) await sendProgressTask(env, { id: job, uid: c.rec.uid }, PROGRESS_SETTLE_S);
}

/**
 * THE RECORD'S LINES BELOW `below` CONFIRMED (`confirmLines`) — called only
 * once a read of the job's row made after those lines were committed found
 * the job still running under its run. True when they are confirmed now or
 * were already; false when the store could not say.
 */
async function confirmProgressLines(env, job, below) {
  if (!Number.isInteger(below) || below <= 0) return true;
  const r = await progressUpdate(env, job, (rec) => {
    if (!rec) return null;
    const next = confirmLines(rec, below);
    return next ? { rec: next } : { done: true };
  });
  return !!r;
}

/**
 * ONE LINE: true when it was committed and more may wait. The lease first;
 * then the job's row — a job that ended, was stopped, was held for review or
 * is another run's now has its record closed and no call made; then the
 * call; then the row AGAIN; then the commit on the etag the commit reads,
 * which a close at the job's end beats (`commitLine` refuses a closed record
 * or a lease no longer this writer's).
 *
 * AND THEN THE ROW A THIRD TIME (2026-10-06): the line is committed
 * unconfirmed, and only a read made after the commit that finds the job still
 * running confirms it — so a commit that lands after the job's end (its close
 * failed or timed out, and the second read came just before the finalize) is
 * never shown. The first read confirms, too, any line the claim found whose
 * own confirmation never landed: it was committed before that read.
 */
/**
 * THE TALK'S OWN DIAGNOSTIC LOG (2026-10-19, owner: "ok do that" — two recorded
 * builds said 4 and 2 lines while their traces show every step reported). One
 * small object per event under `progress-diag/<job>/`, written beside the
 * record and never read by anything that decides a line: what was marked or
 * refused, each writer's claim, the job-row verdict, the model call's outcome
 * and time, each commit. Read by the job's owner only
 * (`GET /api/site/build/<id>/diag`). A failure here never costs anything.
 */
const progressDiagKey = (job) => "progress-diag/" + job + "/";
function diag(env, job, ev, data = {}) {
  try {
    if (!env || !env.SITES_BUCKET || !isJobId(job) || typeof ev !== "string") return;
    const at = Date.now();
    const key = progressDiagKey(job) + String(at).padStart(14, "0") + "-" + Math.random().toString(36).slice(2, 8) + ".json";
    const p = env.SITES_BUCKET.put(key, JSON.stringify({ at, ev, ...data }), { httpMetadata: { contentType: "application/json" } }).catch(() => {});
    return p;
  } catch { /* the log never costs the talk */ }
}
async function writeProgressLine(env0, task, owner) {
  const job = task.id;
  const env = await withKeptEffort(env0, job);
  const claimed = await progressUpdate(env, job, (rec) => {
    if (!rec || rec.uid !== task.uid) return null;
    const c = claimWriter(rec, owner, Date.now());
    return c ? { rec: c.rec, gaveUp: c.gaveUp === true } : null;
  });
  if (!claimed) { diag(env, job, "claim-none", { owner }); return false; }
  diag(env, job, "claimed", { owner, gaveUp: claimed.gaveUp === true, closed: !!(claimed.rec && claimed.rec.closed), lines: claimed.rec && Array.isArray(claimed.rec.lines) ? claimed.rec.lines.length : -1 });
  // EVERY TRY SPENT — a writer whose lease ran out before it committed spent
  // one too: what waited is given up, at no call, and said here.
  if (claimed.gaveUp) { console.log("progress:", job, "given up after", PROGRESS_TRIES, "tries"); return false; }
  const rec = claimed.rec;
  // THE TASKS' LINES FIRST, when the record still needs them: no row is read
  // for them, because they say no state — the page picks the line for the
  // state it reads, so one written after the job ended claims nothing.
  if (tasksNeeded(rec)) return writeTaskLines(env, task, owner, rec);
  // A CLOSED RECORD'S ONE LINE: what the job settled before it ended (`lateBatch`).
  if (rec.closed) return writeLateLine(env, task, owner, rec);
  const batch = batchFor(rec);
  const before = jobVerdict(await jobRowForProgress(env, job), rec, Date.now());
  if (!before.ok) { diag(env, job, "verdict-before", { why: before.why, marks: batch.marks.length }); await progressStops(env, job, owner, batch, before.why); return false; }
  if (unconfirmedLines(rec) > 0) await confirmProgressLines(env, job, rec.lines.length);
  if (!batch.facts.length) { diag(env, job, "no-facts", { marks: batch.marks.length }); await progressUpdate(env, job, (r) => { const out = releaseWriter(r, owner); return out ? { rec: out } : null; }); return false; }
  const model = modelsFor(rec.picker || undefined).quick;
  // THE REQUEST'S OTHER PARTS AS THEY STAND NOW (2026-10-07): read off its
  // record for this line, so the writer is told what is finished and what is
  // still to come, and takes none of it for this job's own work.
  const { others, waited } = await requestOthersFor(env, rec);
  const t0 = Date.now();
  let out;
  try {
    // A CONVERSATIONAL RECORD (talk, 2026-10-13) is written by its own call:
    // nine states, recorded reasons, and an optional explanation.
    // STREAMED (2026-10-19): the sentence so far goes up as it is written.
    const live = rec.talk === true ? liveLineWriter(env, job, rec.lines.length + 1) : null;
    out = await writeProgress({ send: live ? quickSendLive(env, "progress", progressBudget, live) : quickSend(env, "progress", progressBudget) }, { facts: batch.facts, context: progressContext(rec, { others, waited }), model, talk: rec.talk === true, earlier: rec.lines.map((l) => l && l.text) });
  } catch { out = { ok: false, why: "send", usage: [], attempts: 0 }; }
  // AND CLEARED ONCE IT IS DONE, either way — a committed line replaces it.
  if (rec.talk === true) await clearLiveLine(env, job);
  // WHAT IT COST US, IN THE LOG: a line is not charged to the customer, so the
  // ledger never shows it, and this is where attempts, tokens — fresh and
  // cached — and time are read; one string, the shape the reader reads
  // (`usageLogLine`, 2026-10-07).
  try {
    console.log(usageLogLine({ kind: "line", id: job, ok: out.ok, why: out.why, model, milestones: batch.marks.length, facts: batch.facts.length, attempts: out.attempts, usage: out.usage, ms: Date.now() - t0 }));
  } catch { /* a log line never costs the line */ }
  diag(env, job, "call", { ok: !!out.ok, why: out.why || "", ms: Date.now() - t0, attempts: out.attempts || 0, marks: batch.marks.length, facts: batch.facts.length });
  if (!out.ok) {
    const f = await progressUpdate(env, job, (r) => {
      const failed = failBatch(r, { owner, marks: batch.marks, why: out.why, now: Date.now() });
      return failed ? { rec: failed.rec, retry: failed.retry } : null;
    });
    if (f && f.retry) await sendProgressTask(env, { id: job, uid: task.uid }, Math.ceil(PROGRESS_RETRY_MS / 1000));
    return false;
  }
  const after = jobVerdict(await jobRowForProgress(env, job), rec, Date.now());
  if (!after.ok) { diag(env, job, "verdict-after", { why: after.why }); await progressStops(env, job, owner, batch, after.why); return false; }
  const done = await progressUpdate(env, job, (r) => {
    const next = commitLine(r, { owner, marks: batch.marks, text: out.text, explain: out.explain || "", now: Date.now() });
    return next ? { rec: next } : null;
  });
  diag(env, job, done ? "committed" : "commit-refused", {});
  if (!done) return false;
  // CONFIRMED BY A READ MADE AFTER THE COMMIT, covering only the lines this
  // commit's record held — never one a later writer commits meanwhile. A row
  // that could not be read leaves the line for the next writer or the cron; a
  // job no longer running leaves it unshown, and its record closed.
  const post = jobVerdict(await jobRowForProgress(env, job), rec, Date.now());
  if (post.ok) await confirmProgressLines(env, job, done.rec.lines.length);
  else if (post.why !== "unread") { diag(env, job, "verdict-post", { why: post.why }); await progressStops(env, job, owner, batch, post.why); return false; }
  if (!post.ok) diag(env, job, "unconfirmed", { why: post.why });
  return pendingMarks(done.rec).length > 0;
}

/**
 * THE LATE LINE (2026-10-15, `lateBatch`): a job that ended before its line was
 * written is told in one line, written after its end from what it settled —
 * never what it was doing. Committed, already confirmed, only on a read of the
 * job's row that finds it DONE (the evidence its settled facts happened), and
 * only while its final reply is not written: no line ever appears after the
 * reply. An edit's or an addition's job only: a first build's own answer is
 * its account. A job that failed, was cancelled or was taken over gets none.
 */
async function writeLateLine(env, task, owner, rec) {
  const job = task.id;
  const give = (why, final, retry = false) => progressUpdate(env, job, (r) => {
    const out = failLate(r, { owner, why, now: Date.now(), final });
    return out ? { rec: out.rec, retry: out.retry } : null;
  }).then(async (f) => { if (retry && f && f.retry) await sendProgressTask(env, { id: job, uid: task.uid }, Math.ceil(PROGRESS_RETRY_MS / 1000)); return false; });
  if (rec.op !== "edit" && rec.op !== "addon") return give("op", true);
  const batch = lateBatch(rec);
  if (!batch.facts.length) return give("nothing", true);
  const ended = async () => {
    const row = await jobRowForProgress(env, job);
    if (row === undefined) return "unread";
    if (!row || typeof row !== "object" || row.uid !== rec.uid) return "gone";
    // THE RECORD CLOSES BEFORE THE ROW IS FINALIZED: a row still running is
    // read again shortly, never taken for a job that did not finish.
    if (!isTerminalEdit(row.state)) return "unread";
    if (row.state !== "done") return "not-done";
    const rp = await replyRecordAt(env, replyKey(job));
    if (!rp.read) return "unread";
    if (rp.rec && rp.rec.state === "written") return "replied";
    return "ok";
  };
  const before = await ended();
  if (before === "unread") return give("row", false, true);
  if (before !== "ok") return give(before, true);
  const model = modelsFor(rec.picker || undefined).quick;
  const { others, waited } = await requestOthersFor(env, rec);
  const t0 = Date.now();
  let out;
  try {
    out = await writeProgress({ send: quickSend(env, "progress", progressBudget) }, { facts: batch.facts, context: progressContext(rec, { others, waited }), model, talk: rec.talk === true, earlier: rec.lines.map((l) => l && l.text) });
  } catch { out = { ok: false, why: "send", usage: [], attempts: 0 }; }
  try {
    console.log(usageLogLine({ kind: "line", id: job, ok: out.ok, why: out.why, model, milestones: batch.marks.length, facts: batch.facts.length, attempts: out.attempts, usage: out.usage, ms: Date.now() - t0 }) + " late");
  } catch { /* a log line never costs the line */ }
  if (!out.ok) return give(out.why, false, true);
  const after = await ended();
  if (after === "unread") return give("row", false, true);
  if (after !== "ok") return give(after, true);
  await progressUpdate(env, job, (r) => {
    const next = commitLate(r, { owner, marks: batch.marks, text: out.text, explain: out.explain || "", now: Date.now() });
    return next ? { rec: next } : null;
  });
  return false;
}

/**
 * A job's request as its writer reads it: the other parts (`otherParts`) and,
 * on a conversational record, what its own part waited for (`waitedFor`).
 * Both empty for a job no request's, or a request that will not read — a line
 * is never held for them.
 */
async function requestOthersFor(env, rec) {
  if (!rec || !rec.request) return { others: [], waited: [] };
  try {
    const found = await loadRequest(env, rec.slug, rec.request.key);
    return { others: otherParts(rec, found && found.rec), waited: rec.talk === true ? waitedFor(rec, found && found.rec) : [] };
  } catch (e) {
    console.error("progress: could not read the request of", rec.job, errorClassForLog(e));
    return { others: [], waited: [] };
  }
}

/**
 * THE TASKS' LINES: one call (two at most) for every task the record holds
 * with no lines yet, in every state, committed on the lease alone beside those
 * already written; a call that wrote nothing is tried again later, then given
 * up (`tasksWhy`), and the customer's words stay on the card. True when more
 * waits: a task added during the call, or milestones waiting for a line.
 */
async function writeTaskLines(env, task, owner, rec) {
  const job = task.id;
  const model = modelsFor(rec.picker || undefined).quick;
  const t0 = Date.now();
  // ONLY THE TASKS WITH NO LINES YET: a part carved since the last call is
  // written on its own, and the lines already shown are never written again.
  // AT MOST `TASK_BATCH` A CALL (2026-10-06): every task is written in seven
  // states now, so a long request's are written over several calls, each
  // well inside its ceiling; what is left waits, and is asked for at once.
  const tasks = unwrittenTasks(rec).slice(0, TASK_BATCH);
  let out;
  try {
    // A SPLIT REQUEST'S OPENING LINE (2026-10-23), asked for with its first
    // tasks: the number of parts is the fact it is written from.
    const split = rec.op === "request" && !rec.opening && Array.isArray(rec.taskWords) && rec.taskWords.length >= 2 ? rec.taskWords.length : 0;
    out = await writeTasks({ send: quickSend(env, "progress", progressBudget) }, { tasks, context: progressContext(rec), model, split });
  } catch { out = { ok: false, why: "send", usage: [], attempts: 0 }; }
  try {
    console.log(usageLogLine({ kind: "tasks", id: job, ok: out.ok, why: out.why, model, tasks: tasks.length, attempts: out.attempts, usage: out.usage, ms: Date.now() - t0 }));
  } catch { /* a log line never costs the lines */ }
  if (!out.ok) {
    const f = await progressUpdate(env, job, (r) => {
      const failed = failTasks(r, { owner, why: out.why, now: Date.now() });
      return failed ? { rec: failed.rec, retry: failed.retry } : null;
    });
    if (f && f.retry) await sendProgressTask(env, { id: job, uid: task.uid }, Math.ceil(PROGRESS_RETRY_MS / 1000));
    return false;
  }
  const done = await progressUpdate(env, job, (r) => {
    const next = commitTasks(r, { owner, tasks: out.tasks, now: Date.now(), opening: out.opening || "" });
    return next ? { rec: next } : null;
  });
  // MORE TO WRITE — a task added while the call ran, or milestones waiting.
  return !!done && (tasksNeeded(done.rec) || (!done.rec.closed && pendingMarks(done.rec).length > 0));
}

/**
 * ONE PROGRESS TASK OFF THE QUEUE: lines written until nothing waits, the
 * record closes, or `PROGRESS_LINES_PER_TASK` — then whatever is left is asked
 * for again (`askProgress`), so nothing this writer leaves waits for another
 * milestone or a page. Never throws.
 */
async function runProgressTask(env, task, from = "queue") {
  if (!progressOn(env) || !env || !env.SITES_BUCKET || !task) return;
  diag(env, task.id, "writer-start", { from });
  const owner = newLeaseOwner();
  try {
    for (let i = 0; i < PROGRESS_LINES_PER_TASK; i++) {
      if (!(await writeProgressLine(env, task, owner))) break;
    }
    await askProgress(env, task.id, task.uid);
  } catch (e) { console.error("progress: task failed", task.id, errorClassForLog(e)); }
}

/**
 * THE PROGRESS SWEEP, on the two-minute cron: every edit, add-on or build job still
 * running, read off the job table, and its record asked for a writer where a
 * milestone waits and nobody is on it — a message lost, a writer evicted, a
 * retry whose message never came. Inert with progress off.
 */
export async function runProgressSweep(env) {
  if (!progressOn(env) || !env || !env.SITES_BUCKET || !env.SUPABASE_SERVICE_KEY) return;
  let rows = null;
  try {
    const r = await fetch(`${SUPABASE_URL}/rest/v1/edit_jobs?select=id,uid,op,state&op=in.(edit,addon,build)&state=not.in.(done,failed,cancelled,lost)&order=updated_at.desc&limit=50`, { headers: svcHeaders(env) });
    if (r.ok) rows = await r.json();
  } catch (e) { console.error("progress sweep: could not read edit_jobs", errorClassForLog(e)); }
  if (!Array.isArray(rows)) return;
  const now = Date.now();
  for (const j of rows) {
    // A FIRST BUILD'S LINES TOO (round 5): its record is asked for the same way.
    if (!j || !isJobId(j.id) || typeof j.uid !== "string" || !j.uid || (j.op !== "edit" && j.op !== "addon" && j.op !== "build") || isTerminalEdit(j.state)) continue;
    const at = await progressRecordAt(env, j.id);
    if (!at.read || !at.rec) continue;
    // A LINE WHOSE CONFIRMATION NEVER LANDED (2026-10-06): the job's row read
    // now — after the record, so after every line it holds — confirms them
    // while the job still runs. The list above was read before the record,
    // so it proves nothing about them.
    if (unconfirmedLines(at.rec) > 0 && jobVerdict(await jobRowForProgress(env, j.id), at.rec, Date.now()).ok) await confirmProgressLines(env, j.id, at.rec.lines.length);
    if (writerNeeded(at.rec, now) !== "ask") continue;
    await askProgress(env, j.id, j.uid, now);
  }
  // …AND A JOB THAT ENDED BEFORE ITS TASK'S LINES WERE WRITTEN, while its card
  // can still be found (`PROGRESS_DISCOVERY_MS`): the lines say no state, so
  // they are still worth writing, and nothing but this would ask again.
  let ended = null;
  try {
    const since = new Date(now - PROGRESS_DISCOVERY_MS).toISOString();
    const r = await fetch(`${SUPABASE_URL}/rest/v1/edit_jobs?select=id,uid,op,state&op=in.(edit,addon)&state=in.(done,failed,cancelled,lost)&updated_at=gte.${encodeURIComponent(since)}&order=updated_at.desc&limit=50`, { headers: svcHeaders(env) });
    if (r.ok) ended = await r.json();
  } catch (e) { console.error("progress sweep: could not read ended jobs", errorClassForLog(e)); }
  for (const j of Array.isArray(ended) ? ended : []) {
    if (!j || !isJobId(j.id) || typeof j.uid !== "string" || !j.uid || !isTerminalEdit(j.state)) continue;
    const at = await progressRecordAt(env, j.id);
    if (!at.read || !at.rec || !(tasksNeeded(at.rec) || lateNeeded(at.rec)) || writerNeeded(at.rec, now) !== "ask") continue;
    await askProgress(env, j.id, j.uid, now);
  }
}

/**
 * A job's written lines and its task's own lines for a reader (`linesOf`,
 * `saidOf`), and which kind of job its record says it is (`op`, for its
 * outcome): `{ lines, said, op }` — none with progress off, no record, or
 * another owner's record.
 */
async function progressViewFor(env, job, uid) {
  const none = { lines: [], said: null, op: null };
  if (!progressOn(env) || !env || !env.SITES_BUCKET || !isJobId(job)) return none;
  const at = await progressRecordAt(env, job);
  if (!at.rec || at.rec.uid !== uid) return none;
  return { lines: linesOf(at.rec), said: saidOf(at.rec, 0), op: at.rec.op === "edit" || at.rec.op === "addon" ? at.rec.op : null };
}

/**
 * A JOB'S OWN OUTCOME FOR ITS CARD (2026-10-06, `editJobOutcome`): from its row
 * and its stored answer, the kind of job it is read off its record — or, when
 * the record could not say, off its row. Null when neither can.
 */
async function jobOutcomeFor(env, job, row, op) {
  let kind = op === "edit" || op === "addon" ? op : null;
  if (!kind) {
    const r = await jobRowForProgress(env, job);
    kind = r && (r.op === "edit" || r.op === "addon") ? r.op : null;
  }
  return kind ? editJobOutcome(row, kind) : null;
}
/** A job's written lines alone (`progressViewFor`). */
async function progressLinesFor(env, job, uid) {
  return (await progressViewFor(env, job, uid)).lines;
}

/**
 * A FINISHED JOB'S SERVED ANSWER WITH ITS PROGRESS LINES ON IT (`progress`),
 * its task's own lines (`said`) when a page-filed job has them, and its own
 * outcome (`outcome`, 2026-10-06) read from `row` — or the text exactly as it
 * was: progress off, nothing to add, or a body that is not an object.
 */
async function withProgressLines(env, job, uid, text, row = null) {
  if (!progressOn(env)) return text;
  const { lines, said, op } = await progressViewFor(env, job, uid);
  const outcome = row ? await jobOutcomeFor(env, job, row, op) : null;
  if (!lines.length && !said && !outcome) return text;
  let body;
  try { body = JSON.parse(text); } catch { return text; }
  if (!body || typeof body !== "object" || Array.isArray(body)) return text;
  return JSON.stringify({ ...body, ...(lines.length ? { progress: lines } : {}), ...(said ? { said } : {}), ...(outcome ? { outcome } : {}) });
}

/**
 * A REQUEST'S OWN NARRATION RECORD (2026-10-06): where its parts' task lines
 * are kept — a progress record of `op: "request"`, under an id of 32 hex
 * characters made from the site and the request's key, so it lives under
 * `jobs/` with the seven-day sweep and never on the request record, whose etag
 * stays the driver's.
 */
async function requestTasksId(slug, key) {
  return (await sha256hex("request-tasks:" + slug + "/" + key)).slice(0, 32);
}

/**
 * A REQUEST'S NARRATION, KEPT TO ITS PARTS: opened at its acceptance with each
 * part's words (as its card shows them), and given the words of every part
 * carved from another since — a job's held additions, put off for later — so
 * each part gets the model's own line in every state; then a writer is asked
 * for whatever waits. Create-or-add, by compare-and-swap; another owner's
 * record is never touched.
 */
async function syncRequestTasks(env, { slug, key, uid, message, parts, picker }) {
  if (!progressOn(env) || !env || !env.SITES_BUCKET || typeof uid !== "string" || !uid) return;
  const tasks = (Array.isArray(parts) ? parts : [])
    .map((p) => ({ n: p.n, words: String((typeof p.shown === "string" && p.shown) ? p.shown : (p.words || "")).trim() }))
    .filter((t) => Number.isInteger(t.n) && t.words);
  if (!tasks.length) return;
  const id = await requestTasksId(slug, key);
  const r = await progressUpdate(env, id, (rec) => {
    if (!rec) {
      const opened = openRecord({ job: id, uid, slug, op: "request", run: key, words: message, picker, tasks, at: Date.now() });
      return opened ? { rec: opened } : null;
    }
    if (rec.uid !== uid) return null;
    const more = addTasks(rec, tasks);
    if (!more) return null;
    return more.already ? { done: true } : { rec: more.rec };
  });
  if (r) await askProgress(env, id, uid);
}

/**
 * THE SWEEP'S HALF: the request read and its narration kept to its parts —
 * opened where it never was, given any part carved since, and a writer asked
 * for whatever waits with nobody on it. A request that will not read leaves
 * its narration's own waiting lines asked for still.
 */
async function ensureRequestTasks(env, slug, key) {
  if (!progressOn(env) || !env || !env.SITES_BUCKET) return;
  let found = null;
  try { found = await loadRequest(env, slug, key); } catch { found = null; }
  if (found && found.rec) {
    await syncRequestTasks(env, { slug, key, uid: found.rec.uid, message: found.rec.message, parts: found.rec.parts, picker: found.rec.picker });
    return;
  }
  const id = await requestTasksId(slug, key);
  const at = await progressRecordAt(env, id);
  if (at.read && at.rec && writerNeeded(at.rec, Date.now()) === "ask") await askProgress(env, id, at.rec.uid);
}

/** A request's parts' task lines for its view (`requestView`'s `said`), by part: {} with progress off, none written, or another owner's record. */
async function saidForRequest(env, rec) {
  const out = {};
  if (!progressOn(env) || !rec || !Array.isArray(rec.parts) || !env || !env.SITES_BUCKET) return out;
  const at = await progressRecordAt(env, await requestTasksId(rec.slug, rec.key));
  if (!at.rec || at.rec.uid !== rec.uid) return out;
  for (const p of rec.parts) { const said = saidOf(at.rec, p.n); if (said) out[p.n] = said; }
  // AND A SPLIT REQUEST'S OPENING LINE (2026-10-23), under a key no part's
  // number can be (`requestView` reads it as `opening`).
  if (at.rec.opening) out.opening = at.rec.opening;
  return out;
}

/**
 * EACH RUN JOB'S LINES FOR A REQUEST'S VIEW (`requestView`'s `progress`), read
 * at the look and never written onto the request, so the driver's etag is
 * never fought for them. {} with progress off.
 */
/**
 * EACH RUN JOB'S EXECUTION INTERVAL, from its own progress record (2026-10-09,
 * the readiness correction): `{ from: the record's opening, to: its close or
 * null }`, by job id. The record is opened when the job begins running and
 * closed at its end, so this is the job's active execution, never its filing.
 * A job with no readable record is left out.
 */
async function runsForRequest(env, rec) {
  const out = {};
  if (!progressOn(env) || !rec || !Array.isArray(rec.parts)) return out;
  for (const p of rec.parts) {
    for (const j of Array.isArray(p.jobs) ? p.jobs : []) {
      if (!j || j.kind !== "run" || !isJobId(j.id) || Object.hasOwn(out, j.id)) continue;
      const got = await progressRecordAt(env, j.id);
      const r = got.rec;
      if (!r || r.uid !== rec.uid || !Number.isFinite(r.at)) continue;
      out[j.id] = { from: r.at, to: r.closed && Number.isFinite(r.closed.at) ? r.closed.at : null };
    }
  }
  return out;
}

async function progressForRequest(env, rec) {
  const out = {};
  if (!progressOn(env) || !rec || !Array.isArray(rec.parts)) return out;
  for (const p of rec.parts) {
    for (const j of Array.isArray(p.jobs) ? p.jobs : []) {
      if (!j || j.kind !== "run" || !isJobId(j.id) || Object.hasOwn(out, j.id)) continue;
      const lines = await progressLinesFor(env, j.id, rec.uid);
      if (lines.length) out[j.id] = lines;
    }
  }
  return out;
}

/**
 * THIS OWNER'S STANDALONE JOBS ON THE SITE — edits and add-ons the page filed
 * itself, never a request's (whose jobs are named from its key, `readJobKey`,
 * and shown on its card) — that are running or ended within
 * `PROGRESS_DISCOVERY_MS`, each with the words it was asked and its lines, for
 * a page opened later or on another device: the most recent
 * `STANDALONE_JOBS_MAX`, oldest first. Only a job whose record opened is
 * listed: the words are the record's. [] with progress off or on any failure
 * to read, which the page reads as nothing to show.
 */
const STANDALONE_JOBS_MAX = 20;
/**
 * WORK ON A SITE FILED AFTER ONE REQUEST WAS ACCEPTED, FROM ANY TAB OR DEVICE
 * (2026-10-07, Codex's review of the cleanup batch). A page keeps a late-read
 * request's undo offer only when nothing has been asked of the site since, and
 * its own thread cannot see what another tab or another device asked. Every
 * edit, addition, request part and rewrite is a row in `edit_jobs`, so this
 * reads the owner's rows for the site filed after the request's acceptance,
 * less the request's own (their keys name it). `true` when there is one,
 * `false` when the read shows none, `null` when it cannot be told — a read
 * that failed, or one as long as its limit that names only the request's own.
 *
 * AND WHAT LEAVES NO ROW YET, OR NONE AT ALL (2026-10-07, the follow-up pass):
 * a request taken on elsewhere whose first job is not filed yet is seen by its
 * marker (`newerRequestSince`); a site whose edits are no longer queued runs
 * them with no row, so there it cannot be told. What is put back is checked
 * against the table itself when it is used (`freshRecent`), whoever changed
 * the table — the Data panel included, which files no job.
 */
const NEWER_WORK_LIMIT = 50;
// `queued`: whether the site's edits are queued now, as the request handler
// read it — the canary configuration is read at that one fork, never here.
async function newerWorkSince(env, uid, slug, rec, queued) {
  if (!env || !env.SUPABASE_SERVICE_KEY || !rec || !Number.isFinite(rec.at) || typeof rec.key !== "string") return null;
  if (queued !== true) return null;
  try {
    const since = new Date(rec.at).toISOString();
    const r = await fetch(`${SUPABASE_URL}/rest/v1/edit_jobs?select=id,idem_key&uid=eq.${encodeURIComponent(uid)}&slug=eq.${encodeURIComponent(slug)}&created_at=gt.${encodeURIComponent(since)}&order=created_at.asc&limit=${NEWER_WORK_LIMIT}`, { headers: svcHeaders(env) });
    if (!r.ok) return null;
    const rows = await r.json();
    if (!Array.isArray(rows)) return null;
    const theirs = rows.some((j) => { const k = readJobKey(j && j.idem_key); return !(k && k.key === rec.key); });
    if (theirs) return true;
    if (rows.length >= NEWER_WORK_LIMIT) return null;
    return await newerRequestSince(env, slug, rec);
  } catch (e) { console.error("newer work:", slug, errorClassForLog(e)); return null; }
}
/**
 * WHETHER ANOTHER REQUEST WAS TAKEN ON FOR THE SITE SINCE `rec` (2026-10-07):
 * a request's marker (`requests-live/<slug>/<key>`) is written before its
 * record and before its first job, and says when it was taken on (`at`), so a
 * request that has filed nothing yet is still seen. Read from the marker's
 * body, never its upload time: a marker is written again when its request
 * ends. One gone since the list is skipped — the sweep takes only a marker a
 * day past its request's end, or one whose acceptance died — and one that
 * cannot be read, or a list that does not end, cannot be told.
 */
const NEWER_REQUESTS_LIMIT = 100;
async function newerRequestSince(env, slug, rec) {
  if (!env.SITES_BUCKET) return null;
  const listed = await env.SITES_BUCKET.list({ prefix: REQUEST_LIVE_ROOT + slug + "/", limit: NEWER_REQUESTS_LIMIT });
  let unknown = !!(listed && listed.truncated);
  for (const o of (listed && listed.objects) || []) {
    const at = parseLiveKey(o && o.key);
    if (!at || at.slug !== slug || at.key === rec.key) continue;
    let got = null;
    try { got = await env.SITES_BUCKET.get(o.key); } catch { unknown = true; continue; }
    if (!got) continue;
    let mark = null;
    try { mark = JSON.parse(await got.text()); } catch { mark = null; }
    if (!mark || !Number.isFinite(mark.at)) { unknown = true; continue; }
    if (mark.at >= rec.at) return true;
  }
  return unknown ? null : false;
}

async function standaloneJobsFor(env, uid, slug) {
  if (!progressOn(env) || !env || !env.SITES_BUCKET || !env.SUPABASE_SERVICE_KEY) return [];
  const since = new Date(Date.now() - PROGRESS_DISCOVERY_MS).toISOString();
  let rows = null;
  try {
    // ITS STORED ANSWER, BILLING AND REVIEW TOO (2026-10-06): what its own
    // outcome is read from (`editJobOutcome`) — read here, never handed out.
    const r = await fetch(`${SUPABASE_URL}/rest/v1/edit_jobs?select=id,uid,slug,op,state,idem_key,created_at,updated_at,needs_review,billing,result&uid=eq.${encodeURIComponent(uid)}&slug=eq.${encodeURIComponent(slug)}&op=in.(edit,addon)&updated_at=gte.${encodeURIComponent(since)}&order=created_at.desc&limit=${STANDALONE_JOBS_MAX}`, { headers: svcHeaders(env) });
    if (r.ok) rows = await r.json();
  } catch (e) { console.error("standalone jobs: could not read edit_jobs", errorClassForLog(e)); }
  if (!Array.isArray(rows)) return [];
  const out = [];
  // THE NEWEST, READ NEWEST FIRST AND HANDED OUT OLDEST FIRST, so the page
  // draws them in the order they were asked; a busy day never hides the job
  // running now behind older ones.
  for (const j of rows.slice().reverse()) {
    if (!j || !isJobId(j.id) || j.uid !== uid || j.slug !== slug || (j.op !== "edit" && j.op !== "addon") || readJobKey(j.idem_key)) continue;
    const at = await progressRecordAt(env, j.id);
    if (!at.rec || at.rec.uid !== uid) continue;
    const ended = isTerminalEdit(j.state);
    const when = typeof j.updated_at === "number" ? j.updated_at : Date.parse(String(j.updated_at || ""));
    if (ended && !(Number.isFinite(when) && Date.now() - when <= PROGRESS_DISCOVERY_MS)) continue;
    const said = saidOf(at.rec, 0);
    // AN ENDED JOB WHOSE ANSWER DOES NOT SAY WHAT STANDS (2026-10-07) is read
    // with its database record, as the driver and the job poll read it.
    const ev = wantsEvidence(j) ? await endedEvidence(env, j.slug, j.id) : null;
    const outcome = editJobOutcome(ev ? { ...j, migration: ev.migration } : j, j.op);
    out.push({ job: j.id, op: j.op, state: j.state, ended, words: at.rec.words, at: at.rec.at, progress: linesOf(at.rec), ...(said ? { said } : {}), ...(outcome ? { outcome } : {}) });
  }
  return out;
}

/**
 * A QUESTION ASKED AGAIN, ITS NOTE WRITTEN FROM WHAT HAPPENED (2026-10-03):
 * the answers that did not settle it, and whether our own re-asking has
 * stopped. `fallback` is the fixed note (`againNote`), kept when no note can
 * be written or the one written would not fit beside the question.
 */
async function repeatNote(env, { question, earlier, atLimit, request, answers, picker, slug }, fallback) {
  if (!repliesOn(env)) return fallback;
  const read = repeatNoteFacts({ question, earlier, atLimit });
  if (read.skip) return fallback;
  let out;
  try {
    out = await writeReply({ send: mappedSend(env, slug, "site", quickSend(env, "reply", replyBudget)) }, {
      facts: read.facts,
      context: replyContext({ request, answers, site: { slug } }) + "\n\nWRITE A NOTE OF ONE OR TWO SHORT SENTENCES, UNDER 280 CHARACTERS IN ALL.",
      model: modelsFor(picker).quick,
      maxChars: MAX_NOTE_CHARS,
    });
  } catch { out = { ok: false, why: "send", usage: [], attempts: 0 }; }
  try { console.log("reply: note", out.ok ? "written" : "fell back (" + out.why + ")", "attempts", out.attempts); } catch { /* never */ }
  return out.ok ? out.text : fallback;
}

/**
 * THE READ-WIDENING QUESTION, WRITTEN FROM ITS FACTS (decide-all, sec-3): the
 * rules step found a widening that rests on no words of theirs (`widening`:
 * each table, who sees it now, who would after). The same writer and budget
 * as `repeatNote`; the answers stay the step's structured choices. The
 * question code composed (`ask`) is kept only when none can be written.
 */
const WIDENING_QUESTION_CHARS = 240;
async function wideningQuestion(env, { ask, widening, request, answers, picker, slug }) {
  if (!ask || typeof ask.text !== "string" || !repliesOn(env)) return ask;
  const read = wideningFacts(widening, ask.options);
  if (read.skip) return ask;
  let out;
  try {
    out = await writeReply({ send: mappedSend(env, slug, "site", quickSend(env, "reply", replyBudget)) }, {
      facts: read.facts,
      context: replyContext({ request, answers, site: { slug } }) + "\n\nWRITE ONLY THE QUESTION: ONE OR TWO SHORT SENTENCES, UNDER 240 CHARACTERS IN ALL.",
      model: modelsFor(picker).quick,
      maxChars: WIDENING_QUESTION_CHARS,
    });
  } catch { out = { ok: false, why: "send", usage: [], attempts: 0 }; }
  try { console.log("reply: widening question", out.ok ? "written" : "fell back (" + out.why + ")", "attempts", out.attempts); } catch { /* never */ }
  return out.ok && typeof out.text === "string" && out.text.trim() ? { ...ask, text: out.text.trim() } : ask;
}

// ── THE SITE'S LIVE QUESTION, AROUND A ROUTING CALL (2026-10-02) ───────────
//
// Owner: *"Let the router ask a targeted question … support cancellation and a
// changed request, and prevent stale answers from triggering work."* A message
// that answers a question names it (`ask: { id, chosen }`), and the route reads
// the site's one live question (`builder/clarify.mjs`) BEFORE any model call:
// an answer to anything but this owner's pending question is refused here, at
// no cost and with nothing run. A message that names no question closes the
// live one, so an older tab can never answer it afterwards.
const ASK_ID_RE = /^[0-9a-f]{32}$/;

/** What an answer claims: `{ id, chosen }`; `null` for a claim that cannot be read; `undefined` for none. */
function answerClaim(rb) {
  const a = rb ? rb.ask : undefined;
  if (a === undefined || a === null) return undefined;
  if (typeof a !== "object" || Array.isArray(a) || typeof a.id !== "string" || !ASK_ID_RE.test(a.id)) return null;
  return { id: a.id, chosen: a.chosen === true };
}

/** The reply to an answer whose question is not the live one: nothing asked of a model, nothing charged. */
function staleAnswer(why) {
  return Response.json({
    ok: false, error: "stale-question", why: typeof why === "string" ? why : "closed", cost: 0,
    msg: why === "expired"
      ? "That question has expired, so I didn't act on your reply. Tell me what you'd like and I'll take it from there."
      : "That question was already answered or set aside, so I didn't act on your reply. Tell me what you'd like and I'll take it from there.",
  }, { status: 409 });
}

/**
 * A SITE'S PAGE ADDRESSES FROM ITS STORED PAGES — one reader for the page
 * picker's route (`GET /api/site/routes`) and the routing route's digest, so
 * the two cannot disagree about which pages a site has. A part is not a route
 * (a leading `-` on any segment, the container's own rule); home first, the
 * rest in the order the pages were written.
 */
function sitePageRoutes(pages) {
  const routes = (Array.isArray(pages) ? pages : [])
    .map((p) => (p && typeof p.path === "string" ? p.path : ""))
    .map((p) => routeOf(p))
    .filter((p) => p && !/(^|\/)-/.test(p));
  const seen = new Set();
  const uniq = routes.filter((p) => (seen.has(p) ? false : (seen.add(p), true)));
  uniq.sort((a, b) => (a === "/" ? -1 : b === "/" ? 1 : 0));
  return uniq;
}

// THE SITE'S OWN PAGES, FOR THE ROUTER (2026-10-03, the owner's first
// information-limits batch: *"Fix the six-page reload issue and downstream
// page-list truncation so route decisions use complete, authoritative page
// identities rather than a partial browser cache; keep cached markup separate
// from page identity, preserve access checks, and handle an unavailable or
// incomplete inventory without treating an existing page as absent."*). The
// browser kept six pages across a reload, so the router was told six and an
// edit of a site's seventh page became an addition. The route reads the
// verified owner's pages itself — what the site publishes, through the reader
// the page picker uses (`sitePageRoutes`) — bounded in time like the table
// names, and they replace whatever list the browser sent. When it cannot (not
// this owner's site, a store that will not answer, nothing stored, out of
// time), the browser's list is shown as it came and the router is told it may
// be partial (`pagesComplete` false), so a page missing from it is never read
// as one the site lacks (`readEdit`).
const ROUTE_PAGES_MS = 3000;

/** A promise's answer within `ms`, or `null` — a read that throws or runs late changes nothing. */
function withinMs(promise, ms, label, slug) {
  let timer = null;
  return Promise.race([
    Promise.resolve(promise).catch((e) => { console.error(label, slug, errorClassForLog(e)); return null; }),
    new Promise((resolve) => { timer = setTimeout(() => resolve(null), ms); }),
  ]).then((v) => { if (timer) clearTimeout(timer); return v; });
}

/** A routing scope from a body, read strictly: `{ tables }`, 1–32 table names, or null. */
function routeScopeOf(v) {
  if (!v || typeof v !== "object" || Array.isArray(v) || !Array.isArray(v.tables)) return null;
  if (!v.tables.length || v.tables.length > 32 || !v.tables.every((t) => typeof t === "string" && /^[A-Za-z_][A-Za-z0-9_]{0,62}$/.test(t))) return null;
  return { tables: [...new Set(v.tables)] };
}
/** Do two digests list the same pages (as paths, in any order)? An unreadable list is never the same. */
function samePages(a, b) {
  const paths = (d) => (d && Array.isArray(d.pages) ? d.pages.map((p) => (typeof p === "string" ? p : p && typeof p.path === "string" ? p.path : null)) : null);
  const x = paths(a), y = paths(b);
  if (!x || !y || x.some((p) => p === null) || y.some((p) => p === null)) return false;
  const sx = [...new Set(x)].sort(), sy = [...new Set(y)].sort();
  return sx.length === sy.length && sx.every((p, i) => p === sy[i]);
}
/** Two routing calls' usage, added: what a job that asked twice is billed for. */
function sumRouteUsage(a, b) {
  const out = { ...b };
  for (const k of ["in", "out", "cacheRead", "cacheWrite"]) {
    const x = Number(a && a[k]) || 0, y = Number(b && b[k]) || 0;
    if (Object.hasOwn(a || {}, k) || Object.hasOwn(b || {}, k)) out[k] = x + y;
  }
  return out;
}

/**
 * A BUILD'S ANSWER WITH ITS CONFIRMED PROGRESS LINES ON IT (2026-10-15, after
 * run 38646089624, whose press read the build only once it had ended and was
 * handed no line: the poll put lines on its 202s alone). A JSON object body
 * gets `progress` when the build has lines and the body carries none of its
 * own; anything else is sent exactly as it was.
 */
async function withBuildLines(env, jid, uid, status, body, type) {
  let pv = null;
  try { pv = await progressViewFor(env, jid, uid); } catch { pv = null; }
  if (pv && pv.lines.length) {
    try {
      const pb = JSON.parse(body);
      if (pb && typeof pb === "object" && !Array.isArray(pb) && !Object.hasOwn(pb, "progress")) return Response.json({ ...pb, progress: pv.lines }, { status });
    } catch { /* sent as it was */ }
  }
  return new Response(body, { status, headers: { "content-type": type || "application/json" } });
}

async function routeDigest(env, user, rb, { keepPages = false, words = true } = {}) {
  const site = rb && rb.site && typeof rb.site === "object" && !Array.isArray(rb.site) ? rb.site : null;
  if (!site || rb.hasSite !== true) return { site: rb && rb.site, filled: null, pagesFilled: false, pagesComplete: false };
  const slug = typeof rb.slug === "string" ? rb.slug : "";
  if (!/^[a-z0-9][a-z0-9-]{0,80}$/.test(slug)) return { site, filled: null, pagesFilled: false, pagesComplete: false };
  // OWNERSHIP FIRST, ONCE, FOR BOTH READS: nothing of a site leaves for a
  // caller who does not own it.
  const uid = user && user.id;
  const owned = uid ? withinMs(siteOwnerBySlug(slug, env).then((o) => o === uid), ROUTE_PAGES_MS, "route owner:", slug) : Promise.resolve(false);
  // THE SITE'S OWN TABLE NAMES, WHATEVER THE BROWSER SENT (2026-10-05, the
  // owner's review): the browser's list can be one addition's tables alone,
  // so it is never taken for the site's — read for the owner on every call,
  // and the browser's stand only when the read cannot answer.
  // THE SITE INVENTORY (2026-10-25, router-b1): the stored pages are read
  // once, for their addresses and for what each holds, and the stored spec
  // for each table's columns (`routeInventory`). Each read is bounded and
  // fails open: what could not be read is left out of the inventory.
  const [names, src, spec, routeParts] = await Promise.all([
    owned.then((ok) => (ok === true ? withinMs(routeTableNames(env, uid, slug, true), ROUTE_TABLES_MS, "route tables:", slug) : null)),
    // A SCOPED ROUTING (2026-10-15, `routeScope`) keeps the page list its
    // request recorded at acceptance: it is never read, so a page another part
    // has made since cannot change what this call is shown.
    keepPages ? Promise.resolve(null) : owned.then((ok) => (ok === true ? withinMs(loadSiteSource(env, slug), ROUTE_PAGES_MS, "route pages:", slug) : null)),
    owned.then((ok) => (ok === true ? withinMs((async () => {
      const conn = await ownerRowConn(env, slug);
      if (!conn) return { ok: true, spec: { tables: [] } };
      return readStoredSpec(conn);
    })(), ROUTE_TABLES_MS, "route spec:", slug) : null)),
    // THE PARTS, FOR THE SITE MAP'S KEY FACTS (2026-10-26): a footer part's
    // opening hours are the whole site's. Unread, the facts come from the pages.
    keepPages ? Promise.resolve(null) : owned.then((ok) => (ok === true ? withinMs(loadSiteParts(env, slug), ROUTE_PAGES_MS, "route parts:", slug) : null)),
  ]);
  const routes = Array.isArray(src) ? sitePageRoutes(src) : null;
  let inventory = "";
  try {
    const invPages = Array.isArray(src) ? routes.map((route) => { const p = src.find((x) => x && routeOf(x.path) === route); return p && typeof p.source === "string" ? { path: p.path, route, source: p.source } : null; }).filter(Boolean) : null;
    inventory = routeInventory({ pages: invPages, spec: spec && spec.ok === true && spec.spec ? spec.spec : null, label: accessLabel, words, parts: Array.isArray(routeParts) ? routeParts : null });
  } catch (e) { console.error("route inventory:", slug, errorClassForLog(e)); inventory = ""; }
  let out = site;
  // THE THREE KEPT APART (2026-10-05): names read replace the browser's, and so
  // does an empty list — a site read to have no tables is told it has none
  // (`tablesNone`) — while the browser's stand only when the read could not
  // answer (`null`: not the owner, unreadable, out of time).
  const filled = Array.isArray(names) ? names : null;
  if (filled) out = { ...out, tables: filled };
  const pagesFilled = Array.isArray(routes) && routes.length > 0;
  if (pagesFilled) out = { ...out, pages: routes };
  return { site: out, filled, pagesFilled, pagesComplete: pagesFilled, inventory };
}

// ── WHAT THE CONVERSATION IS TOLD ABOUT THE OWNER'S SITE (2026-10-14) ───────
//
// The owner: *"Supply relevant owner-authorized site context beyond names,
// page paths and table names using existing read mechanisms; do not
// indiscriminately include private customer records."* Read only when the
// router has answered that a message is conversation, only for the verified
// owner (`siteOwnerBySlug`, as `routeDigest`), each read bounded in time, and
// each one that cannot answer said as not known (`null`) rather than as none:
//   pages   the stored pages' own words (`extractText`, the text lane's reader)
//   tables  each table's name, its columns and who may read and write it
//           (`readStoredSpec`, `accessLabel`) — never a row
//   files   the owner's file library (`siteUploadList`): name, kind, size,
//           address — never a visitor's upload, never the contents
const CONVERSE_READ_MS = 3000;
async function readConverseContext(env, user, rb, digest) {
  const site = digest && digest.site && typeof digest.site === "object" ? digest.site : {};
  const base = { exists: true, name: typeof site.name === "string" ? site.name : "", url: typeof site.url === "string" ? site.url : "", paths: Array.isArray(site.pages) ? site.pages.filter((p) => typeof p === "string") : [] };
  const slug = typeof rb.slug === "string" && /^[a-z0-9][a-z0-9-]{0,80}$/.test(rb.slug) ? rb.slug : "";
  const uid = user && user.id;
  if (!slug || !uid) return { ...base, pages: null, tables: null, files: null };
  const owned = await withinMs(siteOwnerBySlug(slug, env).then((o) => o === uid), CONVERSE_READ_MS, "converse owner:", slug);
  if (owned !== true) return { ...base, pages: null, tables: null, files: null };
  const [src, spec, files] = await Promise.all([
    withinMs(loadSiteSource(env, slug), CONVERSE_READ_MS, "converse pages:", slug),
    withinMs((async () => {
      const conn = await ownerRowConn(env, slug);
      if (!conn) return { ok: true, spec: { tables: [] } };
      return readStoredSpec(conn);
    })(), CONVERSE_READ_MS, "converse tables:", slug),
    withinMs(env.SITES_BUCKET ? siteUploadList(env, slug) : Promise.resolve(null), CONVERSE_READ_MS, "converse files:", slug),
  ]);
  const routes = Array.isArray(src) ? sitePageRoutes(src) : [];
  const pages = Array.isArray(src)
    ? routes.map((path) => {
      const p = src.find((x) => x && routeOf(x.path) === path);
      let text = "";
      try { text = p ? extractText(p.source).map((it) => it.text).join(" · ") : ""; } catch { text = ""; }
      return { path, text };
    })
    : null;
  // THE SPEC'S TABLES AND THE CATALOG'S UNDECLARED ONES (audit A36-2).
  const tables = converseTables(spec, accessLabel);
  const lib = Array.isArray(files)
    ? files.filter((f) => f && !f.visitor && typeof f.key === "string").map((f) => {
      const name = f.key.slice(("uploads/" + slug + "/").length);
      const kind = uploadKind(name) || "doc";
      const media = kind === "video" || kind === "audio" ? { mime: MEDIA_FORMATS[name.split(".").pop()].mime, ...readStoredMeta(f.meta) } : {};
      return { url: uploadUrl(slug, name), name: f.download ? readDownloadName(f.download) || name : name, kind, size: f.size, ...media };
    })
    : null;
  // THE SITE MAP'S KEY FACTS (2026-10-26), from the pages just read and the parts.
  let keyFacts = "";
  try {
    const cParts = Array.isArray(src) ? await withinMs(loadSiteParts(env, slug), CONVERSE_READ_MS, "converse parts:", slug) : null;
    keyFacts = Array.isArray(src) ? mapFor("text", buildSiteMap({ pages: src, parts: Array.isArray(cParts) ? cParts : [] })) : "";
  } catch { keyFacts = ""; }
  return { ...base, pages, tables, files: lib, draftFirst: draftFirst(env), ...(keyFacts ? { keyFacts } : {}) };
}

/**
 * THE STORED SCHEMA — AND "THE DATABASE IS EMPTY" AS A MEASUREMENT.
 *
 * `SELECT v FROM _meta WHERE k='schema'` used to sit inline behind an
 * `if (adb)`, and every way it could fail arrived as one throw the caller
 * escalated on. The first correction split that into three outcomes and one of
 * the three was still an INFERENCE: a missing `_meta`, or a `_meta` with no
 * schema row, answered `{tables: []}` — from the absence of ONE ROW to the
 * absence of every table. That is the run-47 defect with a different cause, and
 * a site whose declaration this very repair is about is exactly the site it
 * fires on.
 *
 * `readSchemaState` ASKS THE CATALOG FIRST, so `empty` means the catalog
 * confirmed there are no application tables. Four outcomes now:
 *
 *   stored                   — a spec parsed. `missing` may still name live
 *                              tables it does not declare.
 *   empty                    — no spec AND no tables. The honest empty, and the
 *                              only state in which `{tables: []}` is true.
 *   tables-without-metadata   — no spec and the catalog HAS tables.
 *   unreadable               — a read threw or the JSON will not parse.
 *
 * AND THE LAST TWO ARE NOT THE SAME ANSWER. `ok` is about readability alone;
 * `missing` is the disagreement, and the caller RECOVERS or STOPS on it — the
 * owner's own words, in that order.
 */
async function readStoredSpec(conn) {
  const sql = (q, p) => sqlQuery(conn, q, p || []);
  const st = await readSchemaState({ sql, scrub: scrubSecrets });
  return st;
}

/**
 * RECOVER THE TABLES THE SPEC FORGOT, OR STOP — never design against a spec
 * that is missing a table the database really has.
 *
 * READ-ONLY HERE. Nothing is written to `_meta`: the reconciled spec is used
 * for THIS run, and the addon's own apply writes the merged result at the end
 * if it gets that far. A route that repaired somebody's stored schema as a side
 * effect of reading it would be a write nobody asked for, on the money path.
 *
 * A TABLE THAT CANNOT BE RECOVERED SAFELY STOPS THE STEP. `reconcileSpec`
 * verifies every rebuilt declaration through the real `policiesFor`/`grantsFor`
 * and refuses the ones that would change behaviour; what is left over is a live
 * table the designers would not be told about, which is precisely run 47.
 */
/** The revise's sentence for a database it could not read (2026-09-25). */
const REVISE_LOOK_UNREADABLE_MSG = "I couldn't read your site's saved design just now, so I stopped rather than rewrite it and lose your logo or colours — this is on us. Try again in a few minutes.";
const REVISE_DB_UNREADABLE_MSG ="I couldn't read your site's database just now, so I stopped rather than rewrite your pages as if it had none — this is on us. Try again in a few minutes.";

/**
 * THIS REQUEST'S SPEC OVER WHAT THE SITE ALREADY STORES, for the page writer
 * (2026-09-25): tables, functions and outside connections, each by name, the
 * request's own entry winning — it carries the full column objects `_meta`
 * stores as names. A site that stores nothing answers the request's spec.
 */
function withStoredSpec(spec, stored) {
  const byName = (a, b) => {
    const m = new Map();
    for (const x of (Array.isArray(a) ? a : [])) if (x && x.name) m.set(String(x.name).toLowerCase(), x);
    for (const x of (Array.isArray(b) ? b : [])) if (x && x.name) m.set(String(x.name).toLowerCase(), x);
    return [...m.values()];
  };
  const out = { ...spec };
  for (const k of ["tables", "functions", "apis"]) {
    const merged = byName(stored && stored[k], spec && spec[k]);
    if (merged.length) out[k] = merged;
  }
  return out;
}

/**
 * THE TABLES A FORM IN THE WRITTEN FRAME MAY STORE INTO (2026-10-25,
 * frame-parallel): the site's own schema, read the catalog-aware way, read
 * only. `[]` for a site with no database; `[]` too when it cannot be read, so
 * the frame call is told none and a sign-up is answered `cannot` rather than
 * wired to a table nobody checked. Never throws.
 */
async function frameTablesOf(env, slug) {
  try {
    let conn = await siteBackendBySlug(env, slug);
    if (!conn) { const d = await siteBackendDetail(env, slug); conn = d && d.conn ? d.conn : null; }
    if (!conn) return [];
    const r = await specForAddon(conn);
    return r && r.ok ? frameTables(r.spec) : [];
  } catch (e) {
    console.error("frame tables unreadable:", slug, e && e.name);
    return [];
  }
}

async function specForAddon(conn) {
  const st = await readStoredSpec(conn);
  if (!st.ok) return { ok: false, why: st.state + ":" + st.why };
  // A DECLARED COLUMN THE DATABASE DOES NOT HAVE IS NOT OFFERED (2026-10-07,
  // `liveDeclared`): a column the engine could not add stayed declared, and
  // every designer this spec reaches took it as one it could use. Cut to the
  // catalog read above, and named (`unavailable`) for whoever logs it.
  if (!st.missing.length) { const live = liveDeclared(st.spec, st.columns); return { ok: true, spec: live.spec, recovered: [], unavailable: live.missing }; }

  let grants = [], policies = [], triggers = [];
  try {
    [grants, policies, triggers] = await Promise.all([
      sqlQuery(conn, RECOVER_QUERIES.grants),
      sqlQuery(conn, RECOVER_QUERIES.policies),
      sqlQuery(conn, RECOVER_QUERIES.triggers),
    ]);
  } catch (e) {
    // WITHOUT THE PERMISSION SURFACE NOTHING CAN BE VERIFIED, so nothing may be
    // recovered — and a spec still missing a live table must not be designed
    // against.
    return { ok: false, why: "permissions-unreadable" };
  }
  const out = reconcileSpec({ stored: st.spec, live: { columns: st.columns, grants, policies, triggers }, emit: { policiesFor, grantsFor } });
  const left = st.missing.filter((n) => !out.recovered.some((r) => String(r.name).toLowerCase() === String(n).toLowerCase()));
  if (left.length) return { ok: false, why: "unrecoverable-tables", tables: left.slice(0, 8) };
  const live = liveDeclared(out.spec, st.columns);
  return { ok: true, spec: live.spec, recovered: out.recovered.map((r) => r.name), unavailable: live.missing };
}

/**
 * WRITE THE DATABASE NAME ONTO THE OWNERSHIP ROW — the defect's own fix.
 *
 * `saveBackend` claims with `resolution=ignore-duplicates`, which is an INSERT
 * and cannot update the row already there, so a site whose database was made
 * AFTER its first build kept `neon_db: ""` for ever. Five sites are in that
 * state today.
 *
 * NEVER OVERWRITES A VALID SETTING, and the store is what enforces it rather
 * than us: the filter admits only a row whose `neon_db` is still unset, in both
 * spellings that exist in the live table. So this is safe to call on every
 * provision and safe to run twice — the second run matches nothing.
 *
 * ANSWERS, NEVER THROWS. By the time this runs the database is real and the
 * caller's work has succeeded; a Supabase blip must not turn a completed
 * provision into a failure. `healed: false` with a status is the honest answer
 * and the repair script re-reads rather than trusting this.
 */
async function healSiteBackendDb(env, slug, uid, db) {
  const s = String(slug || "").toLowerCase(), u = String(uid || ""), name = String(db || "").trim();
  if (!s || !u || !name) return { ok: false, healed: false, why: "missing-argument" };
  try {
    const r = await fetch(
      `${SUPABASE_URL}/rest/v1/site_backends?slug=eq.${encodeURIComponent(s)}&uid=eq.${encodeURIComponent(u)}&${unsetDbFilter()}`,
      {
        method: "PATCH",
        headers: svcHeaders(env, { "content-type": "application/json", Prefer: "return=representation" }),
        body: JSON.stringify({ neon_db: name }),
        signal: AbortSignal.timeout(10000),
      },
    );
    if (!r.ok) {
      console.error("backend db heal:", s, r.status, (await r.text().catch(() => "")).slice(0, 200));
      return { ok: false, healed: false, status: r.status };
    }
    const rows = await r.json().catch(() => []);
    // AN EMPTY REPRESENTATION IS "ALREADY SET", NOT A FAILURE — the filter
    // matched nothing, which is what a second run looks like and is the
    // property that makes this repeatable.
    return { ok: true, healed: Array.isArray(rows) && rows.length > 0, status: r.status };
  } catch (e) {
    console.error("backend db heal:", s, String((e && e.message) || e));
    return { ok: false, healed: false, why: "threw" };
  }
}

// WHO OWNS A SLUG, cached, for the one read path that needs it.
//
// The third-party API cache keys on the owner (`cacheKey`) because a slug is
// re-claimable: delete a site and the name is free, so a key without it serves
// an answer fetched with one account's credential to whoever takes the slug
// next. That path is public and unauthenticated, so it cannot afford
// `siteBackendRowFresh` — two Supabase round trips, uncached, per visitor read.
//
// ONE COLUMN, memoized for the same five minutes and by the same reasoning as
// the connection lookup beside it: a slug's owner is fixed for the life of the
// site, and only a delete changes it — at which point the entry is stale for at
// most five minutes and the worst it can do is keep a cache warm for a site
// that has gone.
//
// A FAILURE ANSWERS null AND THE CACHE IS SKIPPED, never shared. Uncached is
// slower; a key without an owner is somebody else's data.
const _ownerCache = makeCache({ ttlMs: SITE_CONN_TTL_MS, max: 500 });
const siteOwnerBySlug = memoize(_ownerCache, async (slug, env) => {
  try {
    const r = await fetch(`${SUPABASE_URL}/rest/v1/site_backends?slug=eq.${encodeURIComponent(slug)}&select=uid&limit=1`,
      { headers: svcHeaders(env), signal: AbortSignal.timeout(8000) });
    if (!r.ok) return null;
    const rows = await r.json().catch(() => null);
    return (Array.isArray(rows) && rows[0] && rows[0].uid) || null;
  } catch { return null; }
});

/**
 * IS THIS NAME A SITE? true, false, or null when we could not ask (2026-10-18,
 * audit A03-1/S1-1). `siteOwnerBySlug` answers null for "nobody" and for "the
 * lookup failed" alike, and in a container job — whose gateway refused the
 * owner read — every name read as free. This asks for the name alone, which
 * the gateway admits for any name, and never caches.
 */
async function siteNameTaken(env, slug) {
  try {
    const r = await fetch(`${SUPABASE_URL}/rest/v1/site_backends?slug=eq.${encodeURIComponent(slug)}&select=slug&limit=1`,
      { headers: svcHeaders(env), signal: AbortSignal.timeout(8000) });
    if (!r.ok) return null;
    const rows = await r.json().catch(() => null);
    if (!Array.isArray(rows)) return null;
    return rows.length > 0;
  } catch { return null; }
}

// The same lookup, keeping the OWNER. Everything that writes needs this: a
// connection string alone cannot answer "is this site mine?". Throws rather
// than returning null when the lookup itself fails, so a caller cannot mistake
// "Supabase is down" for "nobody owns this slug".
async function siteBackendRowFresh(env, slug) {
  const g = await fetch(`${SUPABASE_URL}/rest/v1/site_backends?slug=eq.${encodeURIComponent(slug)}&select=neon_db,uid,brief`, { headers: svcHeaders(env), signal: AbortSignal.timeout(12000) });
  if (!g.ok) throw Object.assign(new Error("site lookup failed"), { detail: g.status + " " + (await g.text().catch(() => "")).slice(0, 200) });
  const rows = await g.json();
  const row = Array.isArray(rows) && rows[0];
  if (!row) return null;
  if (!row.neon_db) return { conn: null, uid: row.uid, brief: row.brief || "" };
  // By SLUG. One Neon project per SITE since 2026-07-29 — keyed by the owner, a
  // user's second site would resolve to their FIRST site's project, which is
  // exactly the isolation the change was made to get.
  const proj = await siteNeonProject(env, slug);
  return { conn: proj ? connForDatabase(proj.neon_conn, row.neon_db) : null, uid: row.uid, brief: row.brief || "" };
}

/**
 * THE ATTEMPT NOTES (2026-10-07, `site-provision.mjs`'s rules):
 * `source/<slug>/neon-unrecorded/<attempt>.json`, beside the site's own
 * source, one per attempt to make the site's project — written BEFORE the
 * create, rewritten as its project becomes known, removed once it is settled.
 * Ids, owner, name, why and when — never a connection string. A note written
 * before attempts had ids is keyed by its project. `unrecordedList` throws
 * when it cannot tell, so cannot-tell is never read as "none". The site's
 * delete leaves `source/<slug>/` standing, so a note outlives its site and the
 * project it names is never left untracked by a delete.
 */
const UNRECORDED_PREFIX = (slug) => "source/" + String(slug || "").toLowerCase() + "/neon-unrecorded/";
const unrecordedKey = (key) => String(key || "").replace(/[^A-Za-z0-9_-]/g, "");
async function unrecordedPut(env, slug, rec) {
  if (!env.SITES_BUCKET) throw new Error("no site bucket bound");
  const key = unrecordedKey((rec && (rec.attempt || rec.projectId)) || "");
  if (!key) throw new Error("no attempt or project id to write down");
  const { conn, neon_conn, ...safe } = rec || {};
  await env.SITES_BUCKET.put(UNRECORDED_PREFIX(slug) + key + ".json", JSON.stringify(safe));
}
async function unrecordedList(env, slug) {
  if (!env.SITES_BUCKET) throw new Error("no site bucket bound");
  const out = [];
  let cursor;
  do {
    const page = await env.SITES_BUCKET.list({ prefix: UNRECORDED_PREFIX(slug), ...(cursor ? { cursor } : {}) });
    for (const o of (page && page.objects) || []) {
      const got = await env.SITES_BUCKET.get(o.key);
      if (!got) continue;
      let rec = null;
      try { rec = JSON.parse(await got.text()); } catch { rec = null; }
      if (!rec || typeof rec !== "object" || !(rec.attempt || rec.projectId)) throw new Error("an attempt note could not be read: " + o.key);
      out.push(rec);
    }
    cursor = page && page.truncated ? page.cursor : undefined;
  } while (cursor);
  return out;
}
async function unrecordedClear(env, slug, key) {
  if (!env.SITES_BUCKET) throw new Error("no site bucket bound");
  const k = unrecordedKey(key);
  if (!k) throw new Error("no note to clear");
  await env.SITES_BUCKET.delete(UNRECORDED_PREFIX(slug) + k + ".json");
}
/**
 * IS THIS PROJECT QUEUED FOR TEARDOWN (2026-10-07)? A deleted site's project
 * is handed to `neon_teardown`, and one still waiting there must never be
 * claimed for a site again: the cron would remove it from under the site.
 * Throws when it cannot tell.
 */
async function neonTearingDown(env, projectId) {
  const r = await fetch(`${SUPABASE_URL}/rest/v1/neon_teardown?project_id=eq.${encodeURIComponent(String(projectId || ""))}&select=id&limit=1`,
    { headers: svcHeaders(env), signal: AbortSignal.timeout(12000) });
  if (!r.ok) throw Object.assign(new Error("teardown queue lookup failed"), { detail: r.status + " " + (await r.text().catch(() => "")).slice(0, 200) });
  const rows = await r.json().catch(() => undefined);
  if (!Array.isArray(rows)) throw new Error("teardown queue lookup: the answer could not be read");
  return rows.length > 0;
}

/**
 * A site's Neon project, by slug.
 *
 * `site_project` rather than a column on `site_backends`, and that separation is
 * the whole point: `site_backends` has an own-read RLS policy, so a signed-in
 * user can read their own rows over the REST API — and `neon_conn` carries a
 * PASSWORD. This table has RLS on with NO policies, so only the service key can
 * see it, the same protection `user_site_project` has and for the same reason.
 */
async function siteNeonProject(env, slug) {
  const g = await fetch(
    `${SUPABASE_URL}/rest/v1/site_project?slug=eq.${encodeURIComponent(String(slug || "").toLowerCase())}` +
    // `uid` IS PART OF THE ANSWER, NOT A CONVENIENCE. `site-provision.mjs`
    // refuses a project row it cannot prove belongs to this caller — a site was
    // otherwise provisionable INSIDE ANOTHER ACCOUNT'S Neon project, handing
    // that account's host, role and password to a stranger. That refusal is
    // enforced in the module and the column it refuses on is selected HERE, so
    // omitting it turns the guard into a permanent 502 on the retry path
    // instead of a check. `site_project.uid` is NOT NULL, so an absent key can
    // only ever mean this SELECT did not ask for it.
    "&select=uid,neon_project,neon_branch,neon_role,neon_conn&limit=1",
    { headers: svcHeaders(env), signal: AbortSignal.timeout(12000) });
  // Throws rather than answering null: "Supabase is down" must not read as
  // "this site has no project", which on the write path would create another.
  if (!g.ok) throw Object.assign(new Error("site project lookup failed"), { detail: g.status + " " + (await g.text().catch(() => "")).slice(0, 200) });
  // AN ANSWER THAT CANNOT BE READ THROWS TOO (2026-10-07): read as no rows, it
  // was "this site has no project", and the write path made another.
  const rows = await g.json().catch(() => undefined);
  if (!Array.isArray(rows)) throw Object.assign(new Error("site project lookup failed"), { detail: "the answer could not be read" });
  return rows[0] || null;
}

/**
 * WHAT A SITE LOOKS LIKE — the look, the stylesheet, the logo, the tab icon, the
 * verification tags and the translation cache — read out of R2.
 *
 * All six lived in `_meta`, a key-value table inside the site's own Neon
 * database, beside the things that genuinely describe a database. None of them
 * is a row: they are config for the compiled output, and the compiled output is
 * in the same bucket this reads from. `site-config.mjs` argues it in full.
 *
 * THE LEGACY READER IS THE MIGRATION RAMP AND IT IS READ-ONLY. Every site
 * published before this has its six values in `_meta` and nothing in R2, so a
 * miss falls back and backfills — the `site-routing.mjs` shape, where a fallback
 * makes an empty store slow rather than wrong. It is omitted for a site with no
 * database, which is the state this whole change exists to make possible.
 *
 * A MISSING BUCKET THROWS RATHER THAN ANSWERING EMPTY, which is the same rule
 * one layer down: cannot-tell must never read as nothing-stored, or a live site
 * republishes stripped of its whole design and reports success. `SITES_BUCKET`
 * is also what SERVES the site, so its absence is not a degradation to ride out.
 */
function configDeps(env, slug, db) {
  const bucket = () => {
    if (!env.SITES_BUCKET) throw new Error("no site bucket bound — the stored look is unreadable");
    return env.SITES_BUCKET;
  };
  const deps = {
    get: async (k) => { const o = await bucket().get(k); return o ? await o.text() : null; },
    put: async (k, v) => {
      // A WRITE OUTSIDE ANY TURN KEEPS THE TURN'S STAMP (2026-10-15): the
      // owner's own settings write, say, never clears the fence a stale job
      // would otherwise meet.
      let meta = null;
      if (writesBeside(env)) { try { const h = await bucket().head(k); if (h && h.customMetadata && h.customMetadata.fence) meta = { fence: h.customMetadata.fence }; } catch { /* the write decides */ } }
      await bucket().put(k, v, { httpMetadata: { contentType: "application/json; charset=utf-8" }, ...(meta ? { customMetadata: meta } : {}) });
    },
  };
  // DERIVED FROM THE MODULE'S OWN NAMES, never a second hand-written list: a key
  // spelled differently here reads as a site that never had a look, silently.
  // Our own constants, so the interpolation carries nothing a caller chose.
  if (db) deps.legacy = () => sqlQuery(db, "SELECT k, v FROM _meta WHERE k IN (" + LEGACY_KEYS.map((k) => "'" + k + "'").join(",") + ")");
  return deps;
}

/** Read a site's config. `{ok:false}` means CANNOT TELL — refuse, never publish. */
async function readSiteConfig(env, slug, db, options) {
  return loadConfig(configDeps(env, slug, db), slug, options);
}

/**
 * Change some of a site's config, leaving the rest alone.
 *
 * Load-merge-save rather than a bare write, because every lane names ONE field
 * and a whole-object write there would drop the other five. The read-to-write
 * window is no wider than the one each handler already has: the two writes a
 * publish makes are sequential in one request, and R2 is read-after-write
 * consistent on a key.
 *
 * A load that could not happen REFUSES rather than writing over a config nobody
 * could read. Answers rather than throwing, so a config write can never lose a
 * build that has already succeeded.
 */
async function patchSiteConfig(env, slug, db, patch, fence = null) {
  if (fence) return patchConfigFenced(env, slug, db, patch, fence);
  const deps = configDeps(env, slug, db);
  let cur;
  try { cur = await loadConfig(deps, slug); } catch (e) { return { ok: false, error: String((e && e.message) || e) }; }
  if (!cur.ok) return { ok: false, error: cur.why + ": " + cur.error };
  return saveConfig(deps, slug, withConfig(cur.config, patch));
}

/**
 * THE SAME CHANGE BY A JOB RUNNING BESIDE OTHERS OF ITS REQUEST (2026-10-15,
 * after review): the read and the write are one conditional step on the
 * config's etag, refused when the config carries a later turn's fence. A
 * holder that read the config, paused, lost its turn and came back meets the
 * newer holder's stamp — on the etag (its write is refused and it reads
 * again) or on the read — and writes nothing (`fenced: true`).
 */
async function patchConfigFenced(env, slug, db, patch, fence) {
  if (!env.SITES_BUCKET) return { ok: false, error: "no site bucket bound — the stored look is unreadable" };
  if (fence.lost) return { ok: false, error: TURN_FENCED, fenced: true };
  const key = CONFIG_KEY(slug);
  for (let i = 0; i < 4; i++) {
    let o;
    try { o = await env.SITES_BUCKET.get(key); } catch (e) { return { ok: false, error: "store: " + String((e && e.message) || e) }; }
    if (o && storedFence(o) > fence.gen) return { ok: false, error: TURN_FENCED, fenced: true };
    if (o && !sinceRead(o)) return { ok: false, error: "the config was read without its etag — nothing written" };
    let config;
    if (o) {
      config = readConfig(await o.text());
      if (!config) return { ok: false, error: "unreadable: the stored config could not be parsed" };
    } else {
      // NONE IN R2: the legacy reader's answer, as the unfenced path reads it.
      const cur = await loadConfig(configDeps(env, slug, db), slug);
      if (!cur.ok) return { ok: false, error: cur.why + ": " + cur.error };
      config = cur.config;
    }
    let put;
    try {
      put = await env.SITES_BUCKET.put(key, fenceBytes(writeConfig(withConfig(config, patch)), fence.gen), {
        httpMetadata: { contentType: "application/json; charset=utf-8" }, customMetadata: { fence: String(fence.gen) },
        onlyIf: o ? sinceRead(o) : { etagDoesNotMatch: "*" },
      });
    } catch (e) { return { ok: false, error: String((e && e.message) || e) }; }
    if (put) return { ok: true };
  }
  return { ok: false, error: "the config kept changing under this write" };
}

/**
 * CLAIM A SLUG FOR A SITE THAT HAS NO DATABASE.
 *
 * Owner's call 2026-08-24: a first build is frontend only and provisions no Neon
 * project. But `site_backends` is not a database record — it is the OWNERSHIP
 * record, and everything keys off it: the 409 that stops a stranger publishing
 * over somebody's site, `existing` (which decides whether the next message is a
 * revise), the delete route's authorisation, the Data panel, version history,
 * the backups sweep. A site with no row is a site that can be overwritten by
 * name and can never be deleted through the route.
 *
 * `neon_db: ""` IS A REPRESENTABLE STATE TODAY AND NEEDED NO MIGRATION, which
 * was measured against the live schema rather than assumed: the column is
 * `text NOT NULL` with no default — NOT NULL does not forbid the empty string —
 * and `siteBackendRowFresh` has ALWAYS answered `{conn: null, uid, brief}` for a
 * row whose `neon_db` is falsy. So the ownership half works and the connection
 * half is honestly absent. CLAUDE.md records claim-first as "considered and
 * rejected: `neon_db` is NOT NULL so it needs DDL" — right about the column,
 * wrong about what NOT NULL forbids.
 *
 * THE SAME ATOMIC CLAIM `ensureSiteBackend` USES, and for the same reason: two
 * overlapping first builds of one free name must not both succeed.
 * `ignore-duplicates + return=representation` makes the insert atomic on the
 * primary key — a row back means it is ours, an empty array means somebody else
 * got there first, and that is a 409 rather than a silent overwrite.
 *
 * NOT AN UPSERT, so a revise cannot reach this and blank a live site's
 * `neon_db`. The caller gates on `!existing`; this is the belt behind it.
 */
/**
 * THE SITE THIS CHAT ALREADY BUILT, or null.
 *
 * Scoped to the caller's own uid AND the chat, so it can only ever answer with
 * a site this customer owns.
 *
 * `null` is "this chat has no site"; `undefined` is "we could not tell". BOTH
 * CALLERS TREAT THEM IDENTICALLY TODAY and both are right to — the retry builds
 * either way, and the claim keeps the taken-name sentence either way — so the
 * distinction changes no answer this Worker gives. That is said here rather
 * than dressed up: a sweep drove all three readings through both call sites and
 * found them identical, and the first version of this comment claimed a caller
 * acted on the difference, which was simply not true.
 *
 * It is kept because it is an honest report about THIS function's own
 * knowledge, and because the direction is decided the moment somebody does read
 * it: reading a failed lookup as "no site" costs a duplicate build the customer
 * can see; reading it as "you have one" hands somebody the wrong site and
 * charges nothing to find out. Cannot-tell must never read as there-is-one.
 */
async function siteForChat(env, uid, chatId) {
  if (!uid || !chatId) return null;
  try {
    const q = `${SUPABASE_URL}/rest/v1/site_backends?uid=eq.${encodeURIComponent(uid)}&${CHAT_COLUMN}=eq.${encodeURIComponent(chatId)}&select=slug,neon_db,brief&limit=1`;
    // BOUNDED, because this sits in front of the deposit on the build route: a
    // lookup that never answers would hold a customer's build open on a
    // question it only asks to save them money.
    const r = await fetch(q, { headers: svcHeaders(env), signal: AbortSignal.timeout(10000) });
    if (!r.ok) return undefined;
    const rows = await r.json();
    if (!Array.isArray(rows)) return undefined;
    return rows[0] || null;
  } catch { return undefined; }
}

async function claimSiteSlug(env, slug, uid, brief, chatId = "") {
  const r = await fetch(`${SUPABASE_URL}/rest/v1/site_backends`, {
    method: "POST",
    headers: svcHeaders(env, { "content-type": "application/json", Prefer: "resolution=ignore-duplicates,return=representation" }),
    // The same columns `saveBackend` writes, with an empty database name. The
    // brief rides along here for the same reason it does there: a revise reads
    // it back as the anchor, and it is written exactly once per site.
    //
    // THE CHAT IS OMITTED WHEN THERE IS NONE, never written as null or "". The
    // partial unique index is `where chat_id is not null`, so an absent value is
    // what keeps every unbound site — the 51 that already exist, a harness, a
    // curl — outside the constraint entirely and behaving exactly as before.
    body: JSON.stringify({ slug, uid, neon_db: "", brief: String(brief || "").slice(0, 4000) || null, ...(chatId ? { [CHAT_COLUMN]: chatId } : {}) }),
    signal: AbortSignal.timeout(15000),
  });
  if (!r.ok) {
    throw Object.assign(new Error("could not record the site"), {
      stage: "claim", detail: (await r.text().catch(() => "")).slice(0, 300),
    });
  }
  const rows = await r.json().catch(() => null);
  // AN UNREADABLE BODY IS NOT A LOST RACE. `.catch(() => null)` on a body we
  // asked to have returned means we cannot tell — and treating that as "somebody
  // else owns this" would 409 a build whose row we had just written. The row is
  // there either way; the next request resolves the ownership honestly.
  if (rows === null) return true;
  if (!(Array.isArray(rows) && rows.length > 0)) {
    // ── WHICH CONFLICT, BECAUSE THERE ARE TWO NOW ──────────────────────────
    //
    // `resolution=ignore-duplicates` is `ON CONFLICT DO NOTHING`, which applies
    // to EVERY unique constraint and not only the primary key — so once the
    // partial index on (uid, chat_id) exists, an empty representation means the
    // slug is taken OR this chat already has a site. Left undistinguished, the
    // second would have told a customer "that site name is taken by another
    // account" about their own site under a name nobody else holds: the
    // recorded "a failure that cannot name itself", arriving the same day the
    // constraint does.
    //
    // The pre-build short-circuit answers this case before a penny is spent, so
    // reaching here means two builds of one chat raced. Rare, and it still has
    // to be true. A lookup that cannot answer keeps the older sentence, since
    // the slug conflict is the one that was always possible.
    const mine = chatId ? await siteForChat(env, uid, chatId) : null;
    if (mine && mine.slug) {
      throw Object.assign(new Error("this chat already has a site"), { stage: "claim", conflict: true, chat: true, slug: mine.slug });
    }
    throw Object.assign(new Error("that name is taken"), { stage: "claim", conflict: true });
  }
  return true;
}

/**
 * How many names past the designer's own choice a fresh build will try.
 *
 * A ceiling rather than a target: a build reaching the end of it has an account
 * holding twenty-five sites whose names all start the same way, and answering
 * the designer's own name there is exactly today's behaviour — a revise of the
 * first — which is wrong but is not made worse by giving up.
 */
const MAX_SLUG_TRIES = 25;

/**
 * A NAME NOBODY IS USING, FOR A BUILD THAT IS DEFINITELY A NEW SITE.
 *
 * Owner, 2026-09-11, on the start screen's box: *"if i type in this chatbox its
 * gotta be a fresh build no matter what, unless i select a site"*.
 *
 * WHAT WENT WRONG. The designer invents the name, and if that name is already
 * held BY THIS ACCOUNT the ownership check reads `existing = true` and the whole
 * build becomes a revise of that site — anchored on its stored pages, with the
 * band split switched off (`planRefusal` refuses to split a revise). MEASURED:
 * `saltmarsh-kayak-co`'s second attempt, typed fresh into that box, came back
 * `bands:revise` and went out as one page call against the placeholder its own
 * first attempt had left behind. A build CLAIMS ITS SLUG BEFORE IT GENERATES, so
 * a failed build leaves the name held and the retry can never be a fresh build.
 *
 * WHEN IT APPLIES, and all three are required:
 *   - the DESIGNER chose the name (a customer who names their own site means
 *     that name, and a named slug with an existing row is a revise by
 *     `firstBuild`'s own reading — so there is nothing here to move off);
 *   - the chat is KNOWN to own no site (`chatOwnsNoSite`, positively `null`);
 *   - the name is held BY US. A stranger's name keeps the 409 it has always
 *     had: silently building under a different name would answer a customer's
 *     chosen name by ignoring it.
 *
 * A READ THAT THROWS ANSWERS THE NAME UNCHANGED. Cannot-tell keeps today's
 * behaviour rather than inventing a name off a blip — and the claim below is
 * still atomic, so the narrow race between this read and that write resolves
 * exactly as it always has.
 *
 * THE TRAILING NUMBER IS REPLACED, NOT STACKED: `fretwork-1` tries `fretwork-2`
 * rather than `fretwork-1-2`, which is the shape every numbered site on this
 * platform already has.
 */
async function freeSlugFor(env, wanted, uid) {
  const base = String(wanted || "").replace(/-\d+$/, "") || String(wanted || "");
  // ASKED IN WHAT A CONTAINER JOB MAY READ (2026-10-18, audit A01-1/A08-3/
  // S1-3): whether the account holds `wanted` through its own rows, and each
  // candidate through the existence read. The full row of another account's
  // name was refused there, so this answered `wanted` on every first build
  // and a fresh chat quietly revised the account's earlier site.
  try {
    const own = await fetch(`${SUPABASE_URL}/rest/v1/site_backends?uid=eq.${encodeURIComponent(uid)}&slug=eq.${encodeURIComponent(wanted)}&select=slug&limit=1`,
      { headers: svcHeaders(env), signal: AbortSignal.timeout(10000) });
    if (!own.ok) throw Object.assign(new Error("own name lookup failed"), { detail: String(own.status) });
    const mine = await own.json();
    if (!Array.isArray(mine) || !mine.length) return wanted;
    for (let n = 2; n <= MAX_SLUG_TRIES; n++) {
      // A candidate is a NEW name, so it fits MAX_NEW_SLUG (audit #247).
      const candidate = capNewSlug(base.slice(0, MAX_NEW_SLUG - String(n).length - 1)) + "-" + n;
      if (candidate === wanted) continue;
      const taken = await siteNameTaken(env, candidate);
      if (taken === false) return candidate;
      if (taken === null) throw Object.assign(new Error("name lookup failed"), { detail: candidate });
    }
  } catch (e) {
    console.error("free slug lookup failed:", wanted, e && (e.detail || e.message));
  }
  return wanted;
}

// Provision (or reuse) one site's database, returning its connection string.
// The ordering and the failure paths live in site-provision.mjs, where they are
// tested; this supplies the real Neon and Supabase calls.
// `chatId` DEFAULTS TO NONE, and the addon route's call deliberately passes
// nothing: it makes the database for a site that ALREADY EXISTS, whose binding
// (or deliberate lack of one, for every site built before 2026-09-08) was
// settled when it was built. Only a first build binds.
async function ensureSiteBackend(env, slug, uid, brief, mark, chatId = "") {
  // CLAIMS, not upserts, for the two slug-keyed tables. merge-duplicates is
  // what made the slug race silent (2026-08-13 audit): two overlapping first
  // builds of one free name both passed the pre-check, both created a Neon
  // project, and the second saveProject UPSERT overwrote the winner's
  // connection row — the winner's live site then pointed at the loser's
  // project, and the loser's project was orphaned with no teardown entry (the
  // queue trigger is BEFORE DELETE; an upsert UPDATE never fires it).
  // ignore-duplicates + return=representation makes the insert atomic on the
  // PK: a full representation means the row is ours, an empty one means
  // somebody else already holds the slug. site-provision.mjs decides what
  // losing means at each site — converge at the project, refuse at the slug.
  const claim = async (table, body) => {
    const r = await fetch(`${SUPABASE_URL}/rest/v1/${table}`, {
      method: "POST",
      headers: svcHeaders(env, { "content-type": "application/json", Prefer: "resolution=ignore-duplicates,return=representation" }),
      body: JSON.stringify(body),
      signal: AbortSignal.timeout(15000),
    });
    if (!r.ok) return { ok: false, detail: (await r.text().catch(() => "")).slice(0, 300) };
    const rows = await r.json().catch(() => undefined);
    // AN ANSWER THAT CANNOT BE READ IS NOT A LOST RACE (2026-10-07): `null`
    // says so, and the module reads the row back before concluding anything —
    // read as `false`, it dropped a project whose row had landed.
    if (!Array.isArray(rows)) return { ok: true, claimed: null };
    return { ok: true, claimed: rows.length > 0 };
  };
  // A REAL BINDING, not just a property on the deps object.
  //
  // `saveAuthInfo` and `saveDataInfo` call `lookupProject(slug)` in their
  // bodies, and it existed ONLY as a key in the literal below — so the bare
  // identifier was a ReferenceError on the first line of both, on every build of
  // every site, caught by the best-effort catch around them and silent. That is
  // why `_meta` held nothing but `schema`, and why fixing `.conn` on the NEXT
  // line changed nothing: the line was never reached. Measured 2026-08-04 by
  // making build smoke read the row instead of reasoning about it.
  const lookupProject = (s2) => siteNeonProject(env, s2);
  const conn = await ensureSiteBackendPure({
    lookupSite: (s2) => siteBackendRowFresh(env, s2),
    lookupProject,
    // Where a swallowed best-effort failure goes. Without it a site can be a
    // shell and nothing anywhere says why.
    warn: (m) => console.error(m),
    // Optional. The build route passes its trace so a COLD provision (create the
    // project, poll, create the database, poll, enable auth, enable the Data
    // API) is distinguishable from a WARM one, which is a single lookup.
    mark,
    createProject: (s2, attempt) => createSiteProject(env, s2, attempt),
    // Identity is Neon's now. Idempotent, and run on the reuse path too —
    // see site-provision.mjs for why enabling only at creation is a trap.
    enableAuth: (proj, dbName) => enableNeonAuth(env, proj.neon_project, proj.neon_branch, dbName),
    // Stored in the SITE's own _meta, not in Supabase: it is per-site, it is only
    // ever read on a request that already holds that connection, and it goes when
    // the site does.
    saveAuthInfo: async (dbName, info) => {
      // `.neon_conn`, NOT `.conn`. `siteNeonProject` returns the raw Supabase row
      // and there is no `conn` column on it, so this read `undefined`,
      // `connForDatabase` threw on `new URL(undefined)`, and the catch around
      // this call swallowed it — silently, on every build, since the day it was
      // written. Neither `auth_info` nor `data_api` has ever been written to any
      // site's `_meta`, which is every generated site answering 501 no_backend
      // on every read, every form and every sign-in. Line ~3080 gets it right.
      const proj = await lookupProject(slug);
      if (!proj || !proj.neon_conn) throw new Error("no project connection recorded for " + slug);
      const conn = connForDatabase(proj.neon_conn, dbName);
      await sqlQuery(conn, "CREATE TABLE IF NOT EXISTS _meta (k TEXT PRIMARY KEY, v TEXT)");
      await sqlQuery(conn, "INSERT INTO _meta (k,v) VALUES ('auth_info', ?) ON CONFLICT (k) DO UPDATE SET v=EXCLUDED.v",
        [JSON.stringify(info).slice(0, 20000)]);
    },
    // THE DATA API, AND IT WAS THE HALF THAT WAS NEVER PLUGGED IN. `enableDataApi`
    // was written, documented "FATAL, like enableNeonAuth", and had ZERO callers;
    // site-provision.mjs was already shaped for it and guards with
    // `if (deps.enableData)`, so a missing dep was a SILENT skip — a green build
    // every time. The consequence ran all the way to the visitor: nothing wrote
    // `_meta.data_api`, so `siteDataBase` resolved null and every read and every
    // form on every generated site answered 501 no_backend. With the Worker's own
    // row routes deleted this IS the site's backend, so the site was a shell.
    //
    // Eighth instance in this repo of built-tested-on-disk-and-reachable-by-
    // nothing, and the first one where the guard existed and the dep did not.
    enableData: (proj, dbName) => enableDataApi(env, proj.neon_project, proj.neon_branch, dbName),
    // Same store and same reasoning as the auth endpoint: per-site, read only on
    // a request that already holds that connection, and gone when the site is.
    // The KEY is what `siteDataBase` reads — `siteServiceBase(db, "data_api")` —
    // so it is spelled once here and once there and a test holds them together.
    saveDataInfo: async (dbName, info) => {
      // `.neon_conn`, NOT `.conn`. `siteNeonProject` returns the raw Supabase row
      // and there is no `conn` column on it, so this read `undefined`,
      // `connForDatabase` threw on `new URL(undefined)`, and the catch around
      // this call swallowed it — silently, on every build, since the day it was
      // written. Neither `auth_info` nor `data_api` has ever been written to any
      // site's `_meta`, which is every generated site answering 501 no_backend
      // on every read, every form and every sign-in. Line ~3080 gets it right.
      const proj = await lookupProject(slug);
      if (!proj || !proj.neon_conn) throw new Error("no project connection recorded for " + slug);
      const conn = connForDatabase(proj.neon_conn, dbName);
      await sqlQuery(conn, "CREATE TABLE IF NOT EXISTS _meta (k TEXT PRIMARY KEY, v TEXT)");
      await sqlQuery(conn, "INSERT INTO _meta (k,v) VALUES ('data_api', ?) ON CONFLICT (k) DO UPDATE SET v=EXCLUDED.v",
        [JSON.stringify(info).slice(0, 20000)]);
    },
    dropProject: async (id) => {
      console.error("dropping unrecorded neon project:", id);
      return dropUserProject(env, id);
    },
    // EVERY ATTEMPT WRITTEN DOWN BEFORE ITS CREATE (2026-10-07): one note per
    // attempt beside the site's own source, so a project no row holds is
    // always findable and the next attempt settles it before it makes another
    // (`settleAttempts`). The note never carries a connection string — it
    // carries a password.
    noteUnrecorded: (s2, rec) => unrecordedPut(env, s2, rec),
    unrecorded: (s2) => unrecordedList(env, s2),
    clearUnrecorded: (s2, key) => unrecordedClear(env, s2, key),
    // THE RECOVERY HALF (2026-10-07): the name an attempt's project carries,
    // the projects found under it after a create whose answer was lost, a
    // noted project's connection read from Neon to claim it for the site, and
    // whether a project is already queued for teardown (never claimed then).
    projectName: (s2, attempt) => projectNameForSite(s2, attempt),
    attemptId: () => crypto.randomUUID().replace(/-/g, "").slice(0, 12),
    now: () => Date.now(),
    findProjects: (s2, note) => findSiteProjects(env, (note && note.name) || projectNameForSite(s2, note && note.attempt)),
    adoptProject: (id, hint) => siteProjectDetails(env, id, hint),
    tearingDown: (id) => neonTearingDown(env, id),
    // CLAIMS, not upserts. Both tables are keyed by slug, and merge-duplicates
    // is what made the slug race silent (2026-08-13 audit): two overlapping
    // first builds of one free name both passed the pre-check, both created a
    // Neon project, and the second saveProject UPSERT overwrote the winner's
    // connection row — so the winner's live site pointed at the loser's
    // project, and the loser's project was orphaned with no teardown entry
    // (the queue trigger is BEFORE DELETE; an upsert UPDATE never fires it).
    // ignore-duplicates + return=representation makes the insert atomic on the
    // PK: a full representation means the row is ours, an empty one means
    // somebody else already holds the slug — and site-provision.mjs decides
    // what losing means at each of the two sites.
    saveProject: (s2, u, proj) => claim("site_project", { slug: s2, uid: u, ...proj }),
    createDatabase: (proj, s2) => createSiteDatabase(env, proj.neon_project, proj.neon_branch, proj.neon_role, s2),
    // The brief rides along on the row that claims the slug. ensureSiteBackend
    // returns early when the slug already has a database, so saveBackend runs
    // exactly once per site — which is what keeps a revise's one-line
    // instruction from overwriting the brief the site was built from.
    // The chat is omitted when there is none — see `claimSiteSlug`, which states
    // why an absent value and a null are not the same thing to the index.
    saveBackend: (s2, u, db) => claim("site_backends", { slug: s2, uid: u, neon_db: db, brief: String(brief || "").slice(0, 4000) || null, ...(chatId ? { [CHAT_COLUMN]: chatId } : {}) }),
    connFor: connForDatabase,
    dbNameFor: dbNameForSite,
    // WHICH SERVICE ENDPOINTS THE SITE LACKS, asked through the SAME reader
    // the proxy uses (`siteServiceBase`) — the heal and the 501 must not be
    // two opinions about what "recorded" means. Deliberately NOT the memoized
    // caches (`siteAuthBase`/`siteDataBase`): those can hold a stale null for
    // ten minutes, and the write path deciding whether to heal must read the
    // truth. A read that throws is caught in the module and heals nothing —
    // a database blip must not read as "missing".
    missingServices: async (conn2) => {
      const out = [];
      if (!(await siteServiceBase(conn2, "auth_info"))) out.push("auth");
      if (!(await siteServiceBase(conn2, "data_api"))) out.push("data");
      return out;
    },
  }, { slug, uid });
  // Publish the route so the first visitor read never touches Supabase. Purely
  // an optimisation — the lookup backfills on a miss anyway — so a failure here
  // must not fail a build that has otherwise succeeded.
  await saveRoute(routeDeps(env), slug, conn);
  mark?.("route");
  // AND RECORD THE DATABASE'S NAME ON THE OWNERSHIP ROW.
  //
  // THE ROOT OF THE RUN-47 DEFECT, fixed at the one place every provision
  // passes through. `saveBackend` inside `ensureSiteBackendPure` is an INSERT
  // with `resolution=ignore-duplicates`: for a site whose first build was
  // frontend-only the row ALREADY EXISTS with `neon_db: ""`, so the claim is a
  // no-op and the column stays empty for ever. Five live sites are in that
  // state. Everything downstream then reads `siteBackendBySlug` → null and
  // calls it "this site has no database".
  //
  // THE NAME COMES FROM THE CONNECTION, not from re-deriving it off the slug:
  // this records the database the caller is ACTUALLY about to use, so the row
  // cannot end up naming one nothing connects to. `dbNameFromConn` answers ""
  // for a string it cannot parse and the heal then does nothing, which is the
  // right direction for a line that only decorates a record.
  //
  // AND `dbNameForSite(slug)` WOULD ANSWER THE SAME THING TODAY — MEASURED over
  // ten slugs including the five affected sites, the two agree every time,
  // because the connection is BUILT from `dbNameForSite` a few lines up. So a
  // sweep mutant swapping one for the other is INERT, and is recorded here
  // rather than hunted as a test gap: the difference is not what it computes
  // now, it is which QUESTION it asks. "What database is this connection
  // pointing at" survives a future where the two diverge — an `already exists`
  // recovery, a rename, a name Neon truncated — and "what would we call it"
  // does not. Kept deliberately; the guard asserts the recorded name equals the
  // database that was really made, which is the property either expression has
  // to satisfy.
  //
  // Best-effort and deliberately AFTER the return value is settled: the
  // database exists, the schema is appliable and the caller's work can proceed
  // whether or not this lands. A failure logs; the next provision retries it,
  // and `scripts/backend-repair.mjs` closes the ones that never do.
  await healSiteBackendDb(env, slug, uid, dbNameFromConn(conn));
  // THE LIMITED LOGIN FOR A NEW SITE (2026-10-26). Best-effort: a site
  // without one keeps working on the owner's login, and the backfill tick
  // makes it later (a container job cannot write `site_project`, so a site
  // first provisioned there gets its login from the tick).
  if (!(await siteAppConn(env, slug).catch(() => null))) await provisionAppLogin(env, slug, conn);
  return conn;
}



// The public data API's throttle. Separate table from the auth one so a site
// being hammered with reads cannot evict the counters holding a brute force
// back.
const _dataLimiter = makeLimiter({ windowMs: WINDOW_MS, max: 20000 });
// Tighter than a form post: an upload costs storage, not a row.
const VISITOR_UPLOADS_PER_MIN = 5;
// Sign-in attempts per source per site. Higher than the upload cap because a real
// person legitimately retries a password, and low enough that credential stuffing
// through our proxy is not free. Better Auth throttles on its own side too; this
// is about not being the open front door to it.
const AUTH_PROXY_PER_MIN = 20;
// Checkouts per source per site. A real customer starts one, maybe two if they
// go back and change the basket; nobody legitimately starts ten a minute. Each
// one writes an order row AND calls Stripe on the owner's account, so an
// unlimited version fills their orders list with pending rows and burns their
// API rate limit — an attack on the shop, using their own credentials.
const CHECKOUT_PER_MIN = 6;
// Data reads per source per site. A page legitimately renders several lists, so
// this is generous — the budget it protects is Neon compute, and RLS is what
// protects the rows.
const DATA_PROXY_PER_MIN = 300;
// Error reports from a published page's own browser. Tight, because it is a
// public endpoint that wakes the site's database: a render loop throws hundreds
// of identical errors a second, and the first few say everything.
const SITE_ERROR_PER_MIN = 6;

// The signing key for claim tokens, from the site's own per-site secret in
// `_meta`. It was shared with session tokens until 2026-07-30; sessions are Neon
// Auth's now, so a claim is the only kind left and this is its only reader. The
// derivation is deliberately unchanged — claim links sit in confirmation emails
// for ninety days and altering it would silently void every one already sent.


/**
 * Where this site's Neon Auth server lives.
 *
 * Recorded at build time from the provisioning response. The field NAME in that
 * response is the one thing here not measured against a real project, so this
 * tries the plausible names and then falls back to the first https URL in the
 * body — a provisioning answer for an auth service contains exactly one, and a
 * heuristic that finds it is better than a hard-coded key that silently finds
 * nothing. Tighten it once a real build has logged the shape.
 */
const _siteAuthBase = makeCache({ ttlMs: 600_000, max: 500 });
const siteAuthBase = memoize(_siteAuthBase, async (db) => siteServiceBase(db, "auth_info"));
/**
 * A short-lived anonymous token for the site's Data API.
 *
 * Neon Auth mints it (`GET <auth base>/token/anonymous`), so there is no signing
 * key here and nothing to rotate. Cached well inside its lifetime: these are
 * deliberately short-lived, and a stale one is a 401 on a visitor's first read.
 *
 * NEVER CACHES A FAILURE — `makeCache.set` refuses null — so a site whose auth
 * server was briefly unreachable is slow rather than broken for the whole TTL.
 * The reason is logged, because a missing token is invisible from outside: the
 * request simply goes out bare and Neon answers 400, which is the failure this
 * whole function exists to stop.
 */
const _siteAnonToken = makeCache({ ttlMs: 120_000, max: 500 });
const siteAnonToken = memoize(_siteAnonToken, async (db) => {
  const base = await siteAuthBase(db);
  if (!base) return null;
  const r = await fetch(base + "/token/anonymous", {
    headers: { accept: "application/json" },
    signal: AbortSignal.timeout(8000),
  });
  const text = await r.text().catch(() => "");
  if (!r.ok) {
    console.error("anon token: " + r.status + " " + text.slice(0, 200));
    return null;
  }
  let j = null;
  try { j = JSON.parse(text); } catch { /* reported below */ }
  // The field name is the one thing here not measured against a real project, so
  // the plausible names are tried and then any JWT-shaped string in the body.
  const tok = j && (j.token || j.access_token || j.accessToken || j.jwt);
  if (typeof tok === "string" && tok) return tok;
  const found = /\b(ey[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+)/.exec(text);
  if (found) return found[1];
  console.error("anon token: no token in the response: " + text.slice(0, 200));
  return null;
});

const _siteDataBase = makeCache({ ttlMs: 600_000, max: 500 });
const siteDataBase = memoize(_siteDataBase, async (db) => siteServiceBase(db, "data_api"));

async function siteServiceBase(db, key) {
  const rows = await sqlQuery(db, "SELECT v FROM _meta WHERE k=?", [key]);
  if (!rows[0] || !rows[0].v) return null;
  let info; try { info = JSON.parse(rows[0].v); } catch { return null; }
  const named = info && (info.auth_url || info.url || info.endpoint || info.base_url ||
    (info.auth && (info.auth.url || info.auth.endpoint)));
  const pick = (o, depth = 0) => {
    if (typeof o === "string") return /^https:\/\//.test(o) ? o : null;
    if (!o || typeof o !== "object" || depth > 3) return null;
    for (const v of Object.values(o)) { const hit = pick(v, depth + 1); if (hit) return hit; }
    return null;
  };
  const url = typeof named === "string" && /^https:\/\//.test(named) ? named : pick(info);
  return url ? String(url).replace(/\/+$/, "") : null;
}


/**
 * The idempotency store for this isolate, bound to the request's KV.
 *
 * ONE store at module scope — its in-memory layer is what catches a
 * double-click, and a store made per request would forget the first press
 * before the second arrived. `env` is per request, so the KV half is handed
 * in each time; `SITE_API_CACHE` is optional exactly as it is for the API
 * cache, and a Worker without it keeps the in-isolate layer alone.
 */
// ── A ROUTED ANSWER, KEPT UNDER ITS REQUEST KEY (audit A13-1, 2026-10-23) ──
//
// The owner's choice (1): every answer the routing route gives a site's
// message sent with its key is kept under that key, and the same message sent
// again is answered from it — no model is asked and nothing is charged. Before
// this only accepted edits and additions were answered so; a conversation, a
// question back or any other outcome resent under its key asked the router
// (and the conversation model) again while the ledger's `repeat` took nothing.
// The kept answer is bound to the account, the site and a digest of the
// message (its words and the answer it carries), as `site-idem.mjs` binds a
// key to its body: the same key with other words is refused at no cost. It
// lives in KV with an expiry (`ROUTE_ANSWER_TTL_S`), and an answer that cannot
// be read is no answer: the route runs as it always has, never a guess.
const ROUTE_ANSWER_TTL_S = 86_400;
const routeAnswerId = (slug, key) => "route-answer:" + slug + ":" + key;
async function routeAnswerDigest(uid, slug, rb) {
  const text = JSON.stringify([String(uid || ""), String(slug || ""), rb && typeof rb.message === "string" ? rb.message : null, rb && rb.ask !== undefined ? rb.ask : null]);
  const d = new Uint8Array(await crypto.subtle.digest("SHA-256", new TextEncoder().encode(text)));
  return Array.from(d, (b) => b.toString(16).padStart(2, "0")).join("");
}
/** `{ state: "none" | "ok" | "unread", v }`: a kept answer read whole, or nothing to act on. */
async function readRouteAnswer(env, slug, key, now = Date.now()) {
  const kv = env && env.SITE_API_CACHE;
  if (!kv || typeof kv.get !== "function") return { state: "none", v: null };
  let v;
  try { v = await kv.get(routeAnswerId(slug, key), { type: "json" }); } catch { return { state: "unread", v: null }; }
  if (v === null || v === undefined) return { state: "none", v: null };
  if (!v || typeof v !== "object" || v.v !== 1 || typeof v.uid !== "string" || typeof v.digest !== "string" ||
    typeof v.body !== "string" || !Number.isInteger(v.status) || !Number.isFinite(v.at)) return { state: "unread", v: null };
  if (now - v.at > ROUTE_ANSWER_TTL_S * 1000) return { state: "none", v: null };
  return { state: "ok", v };
}
/** The answer as served, kept under its key; a write that fails keeps nothing and fails nothing. */
async function keepRouteAnswer(env, slug, key, uid, digest, res, now = Date.now()) {
  const kv = env && env.SITE_API_CACHE;
  if (!kv || typeof kv.put !== "function" || !res || res.status !== 200) return;
  try {
    const body = await res.clone().text();
    await kv.put(routeAnswerId(slug, key), JSON.stringify({ v: 1, uid, digest, at: now, status: res.status, body }), { expirationTtl: ROUTE_ANSWER_TTL_S });
  } catch (e) { console.error("route answer keep:", slug, errorClassForLog(e)); }
}

const SITE_IDEM = makeIdem();

async function proxySiteService(env, request, url, slug, path, which, ctx) {
  const db = await siteRowConn(env, slug);
  if (!db) return Response.json({ error: "no such site" }, { status: 404 });
  let base;
  try { base = which === "data" ? await siteDataBase(db) : await siteAuthBase(db); }
  catch { return Response.json({ error: "couldn't reach that just now" }, { status: 503 }); }
  // Not configured is 501 and not 500: the site was built before its auth
  // endpoint was recorded, which a rebuild fixes, and saying so is more use than
  // a generic failure. "A rebuild fixes it" was FALSE until 2026-08-14 — the
  // reuse path called zero deps, so no rebuild ever re-ran the enables or the
  // saves — and is true now because ensureSiteBackend heals missing endpoints
  // on that path, asking this same reader (`siteServiceBase`) whether one is
  // missing.
  if (!base) return Response.json({ error: "this site's backend is not set up yet", code: "no_backend" }, { status: 501 });

  const target = base + "/" + path + (url.search || "");
  const headers = new Headers();
  // Only what the auth server needs. Forwarding the whole header set would carry
  // cookies for gofarther.dev into a third party.
  // `prefer` carries PostgREST's return=representation, which is how an insert
  // answers with the row it created rather than an empty body.
  for (const h of ["content-type", "authorization", "accept", "prefer", "cookie"]) {
    const v = request.headers.get(h);
    if (v) headers.set(h, v);
  }
  // ORIGIN, SET RATHER THAN FORWARDED — and without it NO GENERATED SITE COULD
  // SIGN ANYBODY UP. Measured live 2026-08-04, first run of `member smoke`:
  // `400 MISSING_ORIGIN — "Origin header is required when callbackURL is not an
  // absolute URL"`, on every auth call that is not a plain GET.
  //
  // The header was dropped by the allow-list above, whose reasoning is sound and
  // is about COOKIES: forwarding everything would carry gofarther.dev's cookies to a
  // third party. `Origin` is not a cookie, it is the caller's identity, and the
  // caller here really is this Worker.
  //
  // SET, not forwarded, on purpose. Forwarding trusts whatever the client sent —
  // and this endpoint is public, so that is an attacker-chosen value reaching
  // Better Auth's trusted-origins check. A caller cannot influence this.
  //
  // AND IT IS THE UPSTREAM'S OWN ORIGIN, NOT OURS — which is the fix for a live
  // break, measured 2026-08-11. It used to be `url.origin` (i.e.
  // `https://gofarther.dev`), and Better Auth answered every sign-up and every
  // sign-in with `403 INVALID_ORIGIN`: 33/2 passing the day before, 21/12 after,
  // with nothing in our own diff touching this path. The whole member tier —
  // `user`, `feed`, `admin` — dead on every published site.
  //
  // Better Auth's documented default is that it "trusts the base URL of your app
  // (i.e. baseURL)" and NOTHING else, and Neon's trusted-domain list is a CONSOLE
  // setting per project. A platform that provisions a project per site can never
  // tick that box, so depending on it was depending on a default we do not own —
  // and one that evidently moved. The upstream's own origin is trusted by
  // construction, needs no configuration, and cannot drift.
  //
  // The CSRF protection this check exists for is a browser concept and buys
  // nothing here: the caller is this Worker, server to server, and the value is
  // still ours to set rather than the client's to choose. The real gate on this
  // endpoint is the rate limiter above it.
  let upstreamOrigin = url.origin;
  try { upstreamOrigin = new URL(base).origin; } catch { /* keep ours; a base we cannot parse is one we cannot improve on */ }
  headers.set("origin", upstreamOrigin);
  // A VISITOR HAS NO TOKEN, AND NEON WILL NOT SERVE A REQUEST WITHOUT ONE.
  //
  // Measured 2026-08-04: every public read answered
  // `400 missing authentication credentials: required authorization bearer token
  // in JWT format`. Neon's Data API always runs a request as a Postgres role
  // chosen from the JWT, and the unauthenticated role — `anonymous` — "still
  // uses a JWT, but no user sign-in is required". There is no no-header path.
  //
  // Nothing is signed here: Neon Auth issues the token, so this needs no key and
  // no rotation. It is fetched only for the DATA proxy and only when the caller
  // sent nothing, so a signed-in member's own token is never replaced.
  if (which === "data" && !headers.has("authorization")) {
    const anon = await siteAnonToken(db).catch(() => null);
    if (anon) headers.set("authorization", "Bearer " + anon);
  }
  // Read once and keep it: the notify below needs the row that was submitted,
  // and a Request body can only be consumed a single time.
  // READS ONLY (2026-10-28). A visitor's write is the site's own Worker's;
  // this proxy now serves only the builder's draft preview, which reads.
  if (request.method !== "GET" && request.method !== "HEAD") return Response.json({ error: "method not allowed" }, { status: 405 });
  const sent = undefined;
  try {
    const r = await fetch(target, {
      method: request.method,
      headers,
      body: sent,
      // A redirect is followed here rather than handed to the page: the client is
      // an XHR and cannot act on a 302 from a cross-origin hop.
      redirect: "follow",
      signal: AbortSignal.timeout(15000),
    });
    const body = await r.text();

    // Remembered the moment the upstream answered, BEFORE the notify hooks
    // below run, so a replay arriving while a slow mailer is still going
    // finds the answer already there. Off the customer's wait when the
    // runtime allows it; a store that cannot be written is a possible
    // duplicate, never a lost submission.
    return new Response(body, {
      status: r.status,
      headers: {
        "content-type": r.headers.get("content-type") || "application/json",
        // PostgREST reports the total row count here when asked for it, and a
        // paginated list is useless without it.
        ...(r.headers.get("content-range") ? { "content-range": r.headers.get("content-range") } : {}),
        // THE TWO AUTH HEADERS, WITHOUT WHICH MEMBER ACCOUNTS CANNOT WORK AT ALL.
        // Both are answers, not cookies, and both were being dropped here — so a
        // published page could sign somebody in and then had no way to act as
        // them. Measured live 2026-08-04 and confirmed against both vendors'
        // documentation rather than guessed:
        //
        //   `set-auth-token` — Better Auth's bearer plugin: "After a successful
        //   sign-in, you'll receive a session token in the response headers."
        //   THIS, not the body's `token`, is what `get-session` accepts. Sending
        //   the body value got `200` with a null session — a signed-in visitor
        //   who reads as signed out, on every generated site.
        //
        //   `set-auth-jwt` — Neon's Data API: "Call GET /get-session and copy the
        //   JWT from the Set-Auth-Jwt response header." A Better Auth session
        //   token is NOT a JWT, and the Data API answers `400 not a valid JWT
        //   encoding` — so every `user`, `feed` and `admin` read and write failed.
        //
        // The request-side allow-list above is about protecting gofarther.dev's
        // cookies. These are the auth server's own answers to its own caller, and
        // withholding them just breaks the caller.
        // WHAT THE AUTH SERVER ACTUALLY SENT, names only, and only when asked.
        //
        // Two fixes were built on documentation and both were wrong: the JWT is
        // not an endpoint, and `set-auth-token` never arrives — so Better Auth's
        // bearer plugin is not on in Neon's managed deployment. The client-side
        // diagnostic could only show OUR response, which is rebuilt here, so it
        // could not tell "the server did not send it" from "we dropped it".
        //
        // Gated on a request header so a public endpoint's normal response is
        // unchanged, and NAMES only — a session cookie and a JWT are both
        // credentials, and this reaches a public CI log.
        ...(request.headers.get("x-gofarther-debug") === "headers"
          ? { "x-gofarther-upstream": [...r.headers.keys()].join(",").slice(0, 500) } : {}),
        // THE SESSION COOKIE, RESCOPED — and without it member accounts cannot
        // work at all. Measured 2026-08-04 by asking the auth server what it
        // sends: SIGN-IN answers with `set-cookie` and nothing else, so Neon's
        // managed Better Auth is COOKIE-based; the bearer plugin is off, which
        // is why `set-auth-token` never appeared and two fixes built on it were
        // wrong. With the cookie dropped here the session died at birth, so
        // `get-session` answered `200 null` and there was never a JWT to hand
        // the Data API.
        //
        // TWO REWRITES, and the second is a security matter, not tidiness:
        //
        //   `Domain` is stripped, or the browser refuses a cookie scoped to the
        //   auth server's host when it arrives from gofarther.dev.
        //
        //   `Path` is pinned to this site's own prefix. Every published site is
        //   served from the SAME origin, so a cookie at `Path=/` would be sent
        //   to every other site on gofarther.dev — one barber shop's customer session
        //   travelling to a stranger's site. Scoped here it reaches this slug's
        //   auth and data calls and nothing else.
        //
        // HttpOnly / Secure / SameSite are left exactly as the auth server set
        // them: those are its decisions about its own credential.
        ...(rescopeCookie(r.headers.get("set-cookie"), "/api/db/" + slug + "/")
          ? { "set-cookie": rescopeCookie(r.headers.get("set-cookie"), "/api/db/" + slug + "/") } : {}),
        ...(r.headers.get("set-auth-token") ? { "set-auth-token": r.headers.get("set-auth-token") } : {}),
        ...(r.headers.get("set-auth-jwt") ? { "set-auth-jwt": r.headers.get("set-auth-jwt") } : {}),
      },
    });
  } catch (e) {
    console.error("site " + which + " proxy failed:", slug, path, e && e.message);
    return Response.json({ error: "couldn't reach that just now" }, { status: 503 });
  }
}


// Everything stored under a site's upload prefix, with WHO put it there.
//
// `customMetadata` has to be asked for explicitly on a list — without `include`
// R2 returns only key and size, and every visitor upload would look like one of
// the owner's, which is exactly the distinction the visitor allowance is
// counted on.
/**
 * ONE ATTACHED PHOTOGRAPH STORED AS AN OWNER UPLOAD, by the build that was
 * asked to show it (2026-10-08, H6). The same `handleUpload` the owner's own
 * upload route runs — content-hashed name, the bytes sniffed, the per-site
 * count and size caps — with the ownership gate already passed: the build
 * route has claimed this slug for this account before it gets here. Answers
 * `{ url }` or `{ error }`; never throws.
 */
export async function storeOwnPhoto(env, slug, name, bytes) {
  if (!env.SITES_BUCKET) return { error: "storage not configured" };
  try {
    const r = await handleUpload({
      gate: async () => ({}),
      hash: async (b) => {
        const d = await crypto.subtle.digest("SHA-256", b);
        return [...new Uint8Array(d)].map((x) => x.toString(16).padStart(2, "0")).join("");
      },
      list: async (s2) => siteUploadList(env, s2),
      put: (key, b, ct, meta) => env.SITES_BUCKET.put(key, b, { httpMetadata: { contentType: ct }, ...(meta ? { customMetadata: meta } : {}) }),
      remove: () => {},
    }, { slug, uid: "", bytes, filename: name });
    const j = r && r.body && typeof r.body === "object" ? r.body : null;
    if (r && r.status < 300 && j && typeof j.url === "string" && j.kind !== "doc") return { url: j.url };
    return { error: String((j && j.error) || "it could not be stored").slice(0, 120) };
  } catch (e) {
    return { error: String((e && e.message) || e).slice(0, 120) };
  }
}

/**
 * ANY FILE THE OWNER'S UPLOAD ROUTE TAKES, stored as one of theirs (2026-10-22,
 * the 3D model's .glb, .usdz and poster): `handleUpload`, with its sniff and
 * every cap. Answers `{ url, kind }` or `{ error }`; never throws.
 */
export async function storeOwnFile(env, slug, name, bytes) {
  if (!env.SITES_BUCKET) return { error: "storage not configured" };
  try {
    const r = await handleUpload({
      gate: async () => ({}),
      hash: async (b) => {
        const d = await crypto.subtle.digest("SHA-256", b);
        return [...new Uint8Array(d)].map((x) => x.toString(16).padStart(2, "0")).join("");
      },
      list: async (s2) => siteUploadList(env, s2),
      put: (key, b, ct, meta) => env.SITES_BUCKET.put(key, b, { httpMetadata: { contentType: ct }, ...(meta ? { customMetadata: meta } : {}) }),
      remove: () => {},
    }, { slug, uid: "", bytes, filename: name });
    const j = r && r.body && typeof r.body === "object" ? r.body : null;
    if (r && r.status < 300 && j && typeof j.url === "string") return { url: j.url, kind: j.kind };
    return { error: String((j && j.error) || "it could not be stored").slice(0, 120) };
  } catch (e) {
    return { error: String((e && e.message) || e).slice(0, 120) };
  }
}

/**
 * THE 3D MODEL ROUTE'S STORES, LEDGER AND NETWORK (2026-10-22), for
 * `builder/model3d-route.mjs`. The record of one request is
 * `model3d/<slug>/<key>.json`, written over its etag when the finish claims it.
 */
/**
 * A 3D MODEL'S LINE INTO THE SITE'S TALK RECORD (2026-10-22, owner approved):
 * the same record and room a Publish or Restore press keeps (`actionTalk`,
 * `GET /api/site/talk/<id>`), under the caller's own account, but appended
 * across requests (the start, then each poll), so it is read back and added
 * to; a line the same as the last one is not said twice, and a closed record
 * takes nothing more. Literal lines: no model is asked anything.
 */
async function model3dTalkMark(env, { id, uid, slug, text, end }) {
  if (!talkOn(env) || !env || !env.SITES_BUCKET || !isJobId(id) || typeof uid !== "string" || !uid || typeof text !== "string" || !text) return;
  let rec = null;
  try { const o = await env.SITES_BUCKET.get(actionTalkKey(uid, id)); rec = o ? JSON.parse(await o.text()) : null; } catch { return; }
  if (!rec || typeof rec !== "object" || !Array.isArray(rec.lines)) rec = { v: 1, kind: "model3d", slug: String(slug || ""), lines: [], done: false, at: Date.now() };
  if (rec.done === true) return;
  const last = rec.lines.length ? rec.lines[rec.lines.length - 1] : null;
  if (!(last && last.text === text)) rec.lines.push({ n: rec.lines.length + 1, text });
  if (end) rec.done = true;
  tellRoom(env, actionRoom(id), { lines: rec.lines.map((l) => ({ n: l.n, ms: 0, text: l.text })), closed: rec.done === true, ...(rec.done ? { live: null } : {}) });
  await env.SITES_BUCKET.put(actionTalkKey(uid, id), JSON.stringify(rec), { httpMetadata: { contentType: "application/json" } }).catch((e) => console.error("model3d talk: could not store", id, errorClassForLog(e)));
}
function model3dDeps(env, { slug, uid, auth, origin }) {
  const recKey = (k) => "model3d/" + slug + "/" + k + ".json";
  return {
    falKey: env.FAL_KEY || "",
    // OFF UNLESS SWITCHED ON (owner, 2026-10-22): no customer can buy a 3D model
    // until the paid test passes and MODEL3D_PURCHASES is set to "on".
    off: String(env.MODEL3D_PURCHASES || "").toLowerCase() !== "on",
    origin,
    fetch: (u, o) => fetch(u, { ...(o || {}), signal: AbortSignal.timeout(60000) }),
    now: () => Date.now(),
    readRecord: async (k) => {
      const o = await env.SITES_BUCKET.get(recKey(k));
      if (!o) return null;
      try { return { rec: JSON.parse(await o.text()), etag: o.etag }; } catch { return null; }
    },
    writeRecord: async (k, rec, etag) => {
      const put = await env.SITES_BUCKET.put(recKey(k), JSON.stringify(rec), { httpMetadata: { contentType: "application/json" }, ...(etag ? { onlyIf: { etagMatches: etag } } : {}) });
      return put ? { ok: true, etag: put.etag } : { ok: false };
    },
    debit: (amount, ref) => debitCredits(auth, amount, ref, "model3d", false),
    reverse: (ref, amount) => reverseCredits(env, uid, ref, "model3d-refund", amount),
    balance: () => readCredits(auth),
    storeFile: (name, bytes) => storeOwnFile(env, slug, name, bytes),
    loadPages: () => loadSiteSourceForEdit(env, slug, { checked: true }),
    publish: (pages, label) => recompileAndPublish(env, { slug, pages, label }),
    routeOf,
    talk: (id, text, end) => model3dTalkMark(env, { id, uid, slug, text, end }),
  };
}

async function siteUploadList(env, slug) {
  const out = [];
  let cursor;
  for (;;) {
    const page = await env.SITES_BUCKET.list({ prefix: "uploads/" + slug + "/", cursor, include: ["customMetadata"] });
    for (const o of (page.objects || [])) {
      out.push({
        key: o.key,
        size: o.size,
        // WHAT IT IS, BY ITS NAME (2026-10-14, `uploadKind`): a picture, a
        // document, a video or a recording — and a video's or a recording's
        // stored report (`meta`: its length and frame size, as the owner's
        // browser read them), for the listings and the models' context.
        kind: uploadKind(uploadFileName(o.key)),
        meta: o.customMetadata || {},
        visitor: !!(o.customMetadata && o.customMetadata.visitor),
        // The download name a document was stored under, still encoded — this is
        // transport, and `readDownloadName` is the one thing that decodes it.
        download: (o.customMetadata && o.customMetadata[DOWNLOAD_NAME_KEY]) || "",
        // THE LOGICAL PURCHASE A PHOTOGRAPH WAS BOUGHT FOR (2026-10-09, round 3):
        // how a purchase whose buyer never wrote again is found to have landed.
        purchase: (o.customMetadata && typeof o.customMetadata.purchase === "string" && o.customMetadata.purchase) || "",
      });
    }
    // Same termination rule as deleteSitePrefix: a truncated page with no
    // cursor would otherwise loop forever.
    if (!page.truncated || !page.cursor) return out;
    cursor = page.cursor;
  }
}

/** The pictures and documents of a listing — what their own limits count (2026-10-14). */
const stillUploads = (objs) => (Array.isArray(objs) ? objs : []).filter((o) => !(o && (o.kind === "video" || o.kind === "audio" || o.kind === "model")));
/** A site's video and audio, as the models and the conversation are told them: address, kind, type, size, what the browser reported. */
async function siteMediaFiles(env, slug) {
  const objs = await siteUploadList(env, slug);
  // AS THE DRAFT HAS THE LIBRARY (audit A10-2): a held replacement's stand-in
  // is taken off at Publish, and so is a file held for removal, so neither is
  // offered to a writer (a page pointing at one would go silent once live).
  // A draft that cannot be read leaves the list as stored.
  let ops = [];
  try { const v = await draftView(env, slug); ops = v ? v.ops : []; } catch { ops = []; }
  return objs.filter((o) => o && !o.visitor && (o.kind === "video" || o.kind === "audio") && (!ops.length || heldMediaSource(ops, uploadFileName(o.key)) !== null)).map((o) => {
    const name = uploadFileName(o.key);
    return mediaForModel({ url: uploadUrl(slug, name), name, download: readDownloadName(o.download), kind: o.kind, mime: MEDIA_FORMATS[name.split(".").pop()].mime, size: o.size, ...readStoredMeta(o.meta) });
  });
}

// ── VIDEO AND AUDIO: THE STORE'S HALF (2026-10-14; 2026-10-15) ─────────────
//
// The R2 calls `site-media.mjs`'s handlers are given, for a site's library
// (`site-<slug>`) and for an account's files kept before its site exists
// (`draft-<uid>`). A session is a small JSON record beside the upload, read
// back on every part — so a part can arrive at any Worker, after any
// reconnect, and is checked against what was started — and kept, with what it
// made, after it finishes. Each part's etag is recorded as it lands
// (`media-parts/`). Room is taken in the scope's ledger (`media-ledger/`),
// written only over the etag it was read at — the conditional write this file
// already uses for build claims and replies — so two requests can never both
// take the last room. Expired reservations are dropped, and their uploads
// aborted, by the next write; R2 also aborts an unfinished multipart upload on
// its own after seven days.
const MEDIA_SESSION_PREFIX = (scope) => "media-sessions/" + scope + "/";
const MEDIA_PARTS_PREFIX = (scope, sid) => "media-parts/" + scope + "/" + sid + "/";
const MEDIA_LEDGER_KEY = (scope) => "media-ledger/" + scope + ".json";
const MEDIA_ASSET_KEY = (scope, name) => "media-assets/" + scope + "/" + name + ".json";
/** A rehearsal the CHANGE failed (a value or a rule, Postgres classes 22 and 23) — never a table not live yet, never an unanswered one. */
const heldRefused = (r) => !!(r && r.ok === false && /^2[23]/.test(String(r.code || "")));
/** What a rehearsal's refusal says to the owner, from Postgres's own code (`sqlRehearse`). */
function heldRefusalSaid(r) {
  const code = String((r && r.code) || "");
  if (code === "23505") return "an entry with that value is already there";
  if (code === "23502") return "a value it needs is missing";
  if (code === "23514" || code === "23503") return "a value isn't one the list allows";
  if (/^22/.test(code)) return "a value isn't the right kind for its column (" + String((r && r.message) || "").slice(0, 160) + ")";
  return "the database refused it (" + code + ")";
}
/** A draft file (kept before a site exists): its key, size, kind and stored metadata; expired ones removed. */
async function draftMediaList(env, uid) {
  const out = [];
  let cursor;
  const prefix = "drafts/" + uid + "/";
  for (;;) {
    const page = await env.SITES_BUCKET.list({ prefix, cursor, include: ["customMetadata", "httpMetadata"] });
    for (const o of page.objects || []) {
      const name = o.key.slice(prefix.length);
      const at = o.uploaded instanceof Date ? o.uploaded.getTime() : Date.parse(o.uploaded || "");
      if (Number.isFinite(at) && at + MEDIA_DRAFT_MS < Date.now()) { try { await env.SITES_BUCKET.delete(o.key); } catch { /* next time */ } continue; }
      if (!isMediaName(name)) continue;
      const cm = o.customMetadata || {};
      out.push({ key: o.key, name, size: o.size, kind: mediaKindOf(name.split(".").pop()), mime: MEDIA_FORMATS[name.split(".").pop()].mime, download: readDownloadName(cm.dl), ...readStoredMeta(cm) });
    }
    if (!page.truncated || !page.cursor) return out;
    cursor = page.cursor;
  }
}
// ── ABANDONED UPLOADS RECLAIMED (2026-10-16) ─────────────────────────────────
//
// A session expires 24 h after it starts (`MEDIA_SESSION_MS`); until now its
// record, its part records and its room in the ledger stayed until the next
// upload of that scope happened to clear the room, and the record and parts
// stayed for ever. The two-minute tick now reclaims them, a bounded number per
// tick — and only past an hour's grace after the session's own expiry:
//   - an OPEN session whose bytes never landed has its multipart upload
//     aborted (an abort discards only the unfinished parts; it never removes
//     an object, so a replacement's target is untouched);
//   - an open session whose bytes DID land (its object carries its id) is a
//     finished upload whose record was lost: the file is kept;
//   - either way its room is released, and its record and part records go.
// NOTHING UNDER `uploads/` IS EVER DELETED HERE: a file, a held replacement's
// stand-in and anything a page plays stay. A pre-site draft older than its 7
// days by another day (a build moving it would long since have finished) goes.
//
// FAIR, BOUNDED, RESTARTABLE (2026-10-16, Codex's review of `fbd53dca`). The
// first version listed a page of 100 sessions, looked at 25 and kept its
// cursor whenever it reached 25 — so 25 live sessions at the front kept an
// expired 26th from ever being looked at — and the parts and drafts passes
// always listed their first page, so an expired 101st draft stayed behind 100
// young ones for ever. Now each prefix is walked on its own, in key order:
//   - a tick lists exactly its budget after the last key it reached
//     (`startAfter`), looks at EVERY key it listed, and keeps the last one;
//   - at the end of the prefix it starts again from the front, so every key is
//     looked at within ceil(keys / budget) ticks, and an item that failed is
//     looked at again on the next lap;
//   - the place is a KEY, not an opaque cursor, kept in `media-sweep/cursor.json`
//     per prefix: a key deleted meanwhile (by this sweep or by anyone) still
//     orders the next listing, and a restart, a lost write or an unreadable
//     file only starts that prefix again from the front;
//   - a listing that fails keeps that prefix's place; the other prefixes go on.
const MEDIA_SWEEP_BUDGET = Object.freeze({ sessions: 25, parts: 50, drafts: 50 });
// THE TICK'S STORAGE CALLS, BOUNDED (2026-10-16, Codex's review of
// `68672e86`): every R2 call the sweep makes — its listings, reads, heads,
// writes, deletes and multipart aborts — is counted against a share per
// prefix, so a session with many parts or a page of due items cannot carry
// one tick past its budget, and the sessions cannot starve the parts and the
// drafts. When a share is spent the prefix stops BEFORE the item that ran out
// and keeps its place at the last key fully handled; that item is handled
// again from the start next lap (every step of it is idempotent: an abort is
// proven or kept, the room is released by its answer, part and session
// records are deleted by key). Measured offline at the storage boundary
// (test/serving-recovery-batch.test.mjs, SRB5): on a fixture of 30 expired
// sessions with 12 parts each, 60 orphaned parts and 60 old drafts, the
// unmetered walk spent 220 calls in one tick; metered, the ticks spent 162,
// 164, 45, 45 and 12, each within the 200 below, and reclaimed all of it.
// One call is kept for the cursor's own write.
