                { const rWhy = aRetryWhy || "refused"; const rOk = !!(clean && clean.ok); aMark("retry_reason", rOk ? "ok" : "fail", { step: "add:" + k, reason: rWhy, ok: rOk }); }
                if (clean && !clean.ok && clean.why !== "nothing") rejectReply(ran.raw, "add:" + clean.why);
